-- Vorrats-Aufgaben (rollend-5) in bestehende Flüge einfügen: 174 Aufgaben, 6 Einheiten, mit form und zaehlt (FT-S). Ein Aufruf, eine Transaktion.
select set_config('lock_timeout', '3s', true), set_config('statement_timeout', '60s', true);
do $einspielen$
declare e record; n int; vorher int; gesamt int := 0; fehler text[] := '{}';
begin
  if (select count(*) from pg_attribute where attrelid = 'schule.aufgabe'::regclass and attname in ('form', 'zaehlt') and not attisdropped) <> 2
     or position('x->>''form''' in pg_get_functiondef('schule.aufgaben_einfuegen(bigint, jsonb)'::regprocedure)) = 0 then
    raise exception 'Vorrats-Aufgaben: erst FT-S einspielen (Spalten form/zaehlt, aufgaben_einfuegen)'; end if;
  for e in select * from (values
    (1, 'zahlen.natuerlich', 805, 39, $auf$[{"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In der Zahl 6 083 steht die 8 an der Zehnerstelle: 8 · 10 = ①. Die 6 steht an der Tausenderstelle: 6 · 1 000 = ②. Die Ziffer 0 an der Hunderterstelle trägt nichts bei. Die Zahl ohne die Einer ist deshalb ② + ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [80, 6000, 6080]}, "h": "Wert einer Ziffer = Ziffer mal Wert ihrer Stelle.", "w": "8 · 10 = 80. 6 · 1 000 = 6 000. 6 000 + 80 = 6 080.", "form": "lueckenweg", "zaehlt": "nein", "r": 5806}, {"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tafel zeigt die Ziffern einer Zahl. Schreibe die Zahl.", "grafik": {"typ": "tabelle", "kopf": ["T", "H", "Z", "E"], "zeilen": [["3", "0", "5", "0"]]}}, "o": {"wert": 3050}, "h": "Lies die Tafel von links nach rechts. Eine Null hält die Stelle frei.", "w": "3 Tausender, 0 Hunderter, 5 Zehner, 0 Einer: 3 000 + 50 = 3 050.", "form": "bruecke", "zaehlt": "ja", "r": 5807}, {"l": "stellenwert", "t": "stellenwert", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Anzeige am Eingang eines Museums zeigt die Besucherzahl: 5 Tausender, 0 Hunderter, 7 Zehner, 3 Einer. Danach kommen noch 40 Besucher. Wie viele Besucher sind es dann?"}, "o": {"wert": 5113}, "h": "Schreibe zuerst die Zahl der Anzeige als Ziffern. Dann addiere.", "w": "Anzeige: 5 000 + 70 + 3 = 5 073. Dazu 40: 5 113 Besucher.", "form": "anwenden", "zaehlt": "ja", "r": 5808}, {"l": "zahlwort_zu_ziffern", "t": "zahlwort_zu_ziffern", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim schreibt „drei Millionen vierzigtausendzwölf“ in Ziffern. Zeile 1: Drei Millionen sind 3 000 000. Zeile 2: Vierzigtausend sind 400 000. Zeile 3: Zusammen: 3 000 000 + 400 000 + 12 = 3 400 012. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viele Nullen hat „vierzigtausend“?", "w": "Vierzigtausend sind 40 000 (4 Zehntausender). Richtig: 3 000 000 + 40 000 + 12 = 3 040 012.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5809}, {"l": "zahlwort_zu_ziffern", "t": "zahlwort_zu_ziffern", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Zahlwort heißt „fünfzig Millionen dreihundert“. Aus wie vielen Ziffern besteht die Zahl, wenn du sie aufschreibst?"}, "o": {"wert": 8}, "h": "Schreibe die Zahl zuerst auf. Von rechts: Dreiergruppen.", "w": "50 Millionen = 50 000 000, dazu 300: 50 000 300. Das sind 8 Ziffern.", "form": "umkehren", "zaehlt": "ja", "r": 5810}, {"l": "zahlwort_zu_ziffern", "t": "zahlwort_zu_ziffern", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein meldet: „Wir haben zwei Millionen dreihunderttausendvierzig Euro gespendet.“ Ein anderer Verein hat 2 299 940 € gespendet. Wie viel Euro hat der erste Verein mehr gespendet?"}, "o": {"wert": 100}, "h": "Schreibe die Spende des ersten Vereins zuerst in Ziffern.", "w": "„Zwei Millionen dreihunderttausendvierzig“ sind 2 300 040. 2 300 040 − 2 299 940 = 100.", "form": "anwenden", "zaehlt": "ja", "r": 5811}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 48 000 120 soll in Worten geschrieben werden. Sie hat ① Ziffern. Von diesen ① Ziffern bilden die letzten 6 volle Dreiergruppen. Links bleiben ② Ziffern übrig. Diese ② Ziffern stehen vor dem Wort „Millionen“ und bilden dort die Zahl ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 2, 48]}, "h": "Zähle alle Ziffern. Die übrigen Ziffern stehen ganz links in der Zahl.", "w": "Die Zahl hat 8 Ziffern. 6 Ziffern sind volle Gruppen, links bleiben 2: Sie bilden 48 und werden „achtundvierzig Millionen“ gelesen. Die mittlere Gruppe 000 wird nicht gelesen. Zahlwort: achtundvierzig Millionen einhundertzwanzig.", "form": "lueckenweg", "zaehlt": "nein", "r": 5812}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Wege für die Zahl 20 305 060: Weg A teilt von rechts in Dreiergruppen. Weg B rechnet: Zahl der Ziffern minus 3 minus 3. Wie viele Ziffern hat die Gruppe ganz links?"}, "o": {"wert": 2}, "h": "Zähle zuerst alle Ziffern der Zahl.", "w": "Die Zahl hat 8 Ziffern. Zwei volle Gruppen sind 6 Ziffern. Es bleiben 8 − 6 = 2 Ziffern ganz links: „zwanzig“.", "form": "zwei_wege", "zaehlt": "ja", "r": 5813}, {"l": "ziffern_zu_zahlwort", "t": "ziffern_zu_zahlwort", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tafel zeigt, wie viele Millionen, Tausender und Einer eine Zahl hat. Welches Zahlwort gehört zu der Zahl?", "grafik": {"typ": "tabelle", "kopf": ["Mio.", "Tsd.", "Einer"], "zeilen": [["7", "305", "40"]]}}, "a": ["sieben Millionen dreihundertfünfvierzig", "sieben Millionen dreihundertfünftausendvierhundert", "sieben Millionen dreihundertfünftausendvierzig", "siebenhundertdreißigtausendfünfhundertvierzig"], "o": {"index": 2}, "h": "Lies die Gruppen von links nach rechts. Hinter jeder Gruppe steht ihr Wort.", "w": "7 Millionen, 305 Tausender, 40 Einer: sieben Millionen dreihundertfünftausendvierzig. Die Zahl ist 7 305 040.", "form": "bruecke", "zaehlt": "ja", "r": 5814}, {"l": "strahl_ablesen", "t": "strahl_ablesen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Zahlenstrahl geht von 200 bis 600 und hat 8 Abschnitte. Der Pfeil steht 5 Abschnitte nach dem Anfang. Kim liest ihn ab. Zeile 1: Abschnittswert: 600 : 8 = 75. Zeile 2: Der Pfeil liegt 5 Abschnitte weiter: 5 · 75 = 375. Zeile 3: Die Zahl am Pfeil ist 200 + 375 = 575. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie wird der Abschnittswert berechnet: Was gehört in die Klammer?", "w": "Der Abschnittswert ist (Ende − Anfang) : Abschnitte = (600 − 200) : 8 = 50. Der Pfeil zeigt 200 + 5 · 50 = 450.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5815}, {"l": "strahl_ablesen", "t": "strahl_ablesen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Zahlenstrahl hat gleich große Abschnitte. Welche Rechnung gibt die Zahl am Pfeil?", "grafik": {"typ": "zahlenstrahl", "start": 300, "ende": 700, "abschnitte": 8, "beschriftet": "anfang_ende", "pfeil": 3}}, "a": ["300 + 3 · 50", "3 · 50", "300 + 3 · 8", "700 − 3 · 50"], "o": {"index": 0}, "h": "Zuerst: Wie viel ist ein Abschnitt wert? Dann: Von welcher Zahl aus zählst du?", "w": "Abschnittswert: (700 − 300) : 8 = 50. Der Pfeil steht 3 Abschnitte nach dem Anfang: 300 + 3 · 50 = 450.", "form": "bruecke", "zaehlt": "ja", "r": 5816}, {"l": "strahl_ablesen", "t": "strahl_ablesen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Laufstrecke ist als Zahlenstrahl von 1 000 m bis 2 000 m gezeichnet, mit 10 gleich großen Abschnitten. Eine Läuferin steht 7 Abschnitte nach dem Anfang. Dann läuft sie noch 150 m weiter. Bei welcher Meterzahl ist sie dann?"}, "o": {"wert": 1850, "einheit": "m"}, "h": "Wie viel Meter ist ein Abschnitt? Die Strecke beginnt nicht bei 0.", "w": "Ein Abschnitt: 1 000 m : 10 = 100 m. 1 000 + 700 = 1 700. Dazu 150: 1 850 m.", "form": "anwenden", "zaehlt": "ja", "r": 5817}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Strahl geht von 2 000 bis 3 000 und hat 5 Abschnitte. Ein Abschnitt ist (3 000 − 2 000) : 5 = ① wert. Die Zahl 2 600 liegt (2 600 − 2 000) : ① = ② Abschnitte nach dem Anfang.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [200, 3]}, "h": "Erst den Abschnittswert, dann die Strecke vom Anfang bis zur Zahl.", "w": "1 000 : 5 = 200. 600 : 200 = 3 Abschnitte.", "form": "lueckenweg", "zaehlt": "nein", "r": 5818}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Auf einem Zahlenstrahl liegt die Zahl 4 500 genau 3 Abschnitte nach dem Anfang. Ein Abschnitt ist 500 wert. Bei welcher Zahl beginnt der Strahl?"}, "o": {"wert": 3000}, "h": "Gehe vom Pfeil rückwärts zum Anfang. Wie weit ist das in Zahlen?", "w": "3 Abschnitte sind 3 · 500 = 1 500. 4 500 − 1 500 = 3 000. Der Strahl beginnt bei 3 000.", "form": "umkehren", "zaehlt": "ja", "r": 5819}, {"l": "strahl_eintragen", "t": "strahl_eintragen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst 3 700 auf einem Zahlenstrahl von 3 000 bis 4 000 mit 10 gleich großen Abschnitten eintragen. Welcher Weg führt zum Ziel?"}, "a": ["3 700 : 10 = 370 Abschnitte nach dem Anfang zählen", "3 700 − 10 = 3 690 Abschnitte nach dem Anfang zählen", "Vom Ende aus 3 000 Abschnitte zurückzählen", "Abschnittswert 100 bestimmen, dann (3 700 − 3 000) : 100 = 7 Abschnitte nach dem Anfang zählen"], "o": {"index": 3}, "h": "Frage dich zuerst: Wie viel ist ein Abschnitt wert?", "w": "Abschnittswert: 1 000 : 10 = 100. Der Abstand zum Anfang ist 700. 700 : 100 = 7 Abschnitte.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5820}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vergleicht 89 999 und 101 000. Zeile 1: 89 999 hat 5 Stellen. Zeile 2: 101 000 hat 6 Stellen. Zeile 3: Die Zahl der Stellen ist egal. Ich vergleiche nur die erste Ziffer: 8 ist größer als 1. Zeile 4: Also ist 89 999 die größere Zahl. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Wann darfst du direkt von links Ziffer für Ziffer vergleichen?", "w": "Hat eine Zahl mehr Stellen, ist sie größer. Erst bei gleich vielen Stellen vergleichst du von links. 101 000 ist größer als 89 999.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5821}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Drei Zahlen: 48 205, 48 250 und 48 025. Weg A vergleicht von links Ziffer für Ziffer. Weg B zieht von jeder Zahl 48 000 ab und vergleicht die Reste. Wie groß ist der Unterschied zwischen der größten und der kleinsten Zahl?"}, "o": {"wert": 225}, "h": "Beide Wege geben dieselbe Reihenfolge der Zahlen.", "w": "Reste: 205, 250 und 25. Größte: 48 250, kleinste: 48 025. 250 − 25 = 225.", "form": "zwei_wege", "zaehlt": "ja", "r": 5822}, {"l": "vergleichen", "t": "vergleichen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Drei Städte haben diese Einwohnerzahlen: Stadt A 1 204 350, Stadt B 1 240 035, Stadt C 1 204 530. Wie viele Einwohner mehr hat die größte Stadt als die kleinste?"}, "o": {"wert": 35685}, "h": "Ordne zuerst die drei Zahlen. Vergleiche von links.", "w": "Größte: B mit 1 240 035. Kleinste: A mit 1 204 350. Unterschied: 1 240 035 − 1 204 350 = 35 685.", "form": "anwenden", "zaehlt": "ja", "r": 5823}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zahl 48 372 wird auf Hunderter gerundet. Rechts neben der Hunderterstelle steht die Ziffer ①. Ist ① gleich 5 oder mehr, wird die Hunderterziffer 3 um 1 größer: Sie wird zur ②. Die gerundete Zahl hat vorn 48 dann die Hunderterziffer ② und dahinter zwei Nullen. Sie ist um ③ größer als 48 372.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 4, 28]}, "h": "Welche Ziffer steht direkt rechts von der Hunderterstelle?", "w": "Rechts der Hunderterstelle steht die 7. Also aufrunden: aus 3 wird 4. Dahinter Nullen: 48 400. 48 400 − 48 372 = 28.", "form": "lueckenweg", "zaehlt": "nein", "r": 5824}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl wurde auf Tausender gerundet und ergibt 65 000. Welche ist die kleinste Zahl, die beim Runden auf Tausender zu 65 000 wird?"}, "o": {"wert": 64500}, "h": "Ab welcher Ziffer rechts wird aufgerundet? Gehe von 65 000 aus nach unten.", "w": "Aufgerundet wird ab 500. 65 000 − 500 = 64 500. Die Zahl 64 499 würde schon zu 64 000.", "form": "umkehren", "zaehlt": "ja", "r": 5825}, {"l": "runden_regel", "t": "runden_regel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Stadion fasst 52 487 Zuschauer. Die Zeitung rundet auf Hunderter. Ein Imbiss plant 300 Portionen weniger als die Zahl der Zeitung. Mit wie vielen Portionen plant er?"}, "o": {"wert": 52200}, "h": "Runde zuerst. Dann ziehe ab.", "w": "Die Hunderter-Rundung von 52 487 ist 52 500. 52 500 − 300 = 52 200.", "form": "anwenden", "zaehlt": "ja", "r": 5826}, {"l": "runden_uebertrag", "t": "runden_uebertrag", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rundet 3 996 auf Zehner. Zeile 1: Die Einerziffer 6 ist 5 oder mehr: Es wird aufgerundet. Zeile 2: Aus 9 + 1 wird 10: Ich schreibe 0 an die Zehnerstelle und vergesse die 1. Zeile 3: Die Hunderterziffer bleibt 9. Gerundet: 3 900. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wohin gehört die 1 aus der 10?", "w": "Die 1 muss an die Hunderterstelle weitergegeben werden: 9 + 1 = 10, wieder mit Übertrag. 3 996 wird zu 4 000.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5827}, {"l": "runden_uebertrag", "t": "runden_uebertrag", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Zahl 2 995 wird auf Hunderter gerundet. Weg A: Ziffer rechts der Hunderterstelle ansehen und aufrunden. Weg B: die zwei nächsten glatten Hunderterzahlen auf dem Zahlenstrahl suchen und die näher liegende nehmen. Um wie viel unterscheidet sich die gerundete Zahl von 2 995?"}, "o": {"wert": 5}, "h": "Beide Wege geben dieselbe gerundete Zahl.", "w": "Weg A: Rechts steht die 9, also aufrunden: 3 000. Weg B: 2 900 ist 95 entfernt, 3 000 nur 5. Unterschied: 3 000 − 2 995 = 5.", "form": "zwei_wege", "zaehlt": "ja", "r": 5828}, {"l": "runden_uebertrag", "t": "runden_uebertrag", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Tacho eines Autos zeigt 19 960 km. Der Händler schreibt in die Anzeige die Zahl auf Hunderter gerundet. Wie viele Kilometer ist die Zahl in der Anzeige größer als die Tacho-Anzeige?"}, "o": {"wert": 40, "einheit": "km"}, "h": "Runde zuerst. Vorsicht: Die 9 gibt die 1 weiter.", "w": "19 960 auf Hunderter gerundet: 20 000. 20 000 − 19 960 = 40 km.", "form": "anwenden", "zaehlt": "ja", "r": 5829}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine Zeitung schreibt über 4 987 Besucher. Auf Hunderter gerundet sind das ①. Der Veranstalter rechnet genau ab: Jeder Besucher zahlt 2 €. Das sind ② €. Mit der gerundeten Zahl wären es ① · 2 = ③ €, also 26 € zu viel.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5000, 9974, 10000]}, "h": "Runden darf man für eine Meldung. Für die Abrechnung nimmst du die genaue Zahl.", "w": "4 987 ≈ 5 000. Genau: 4 987 · 2 = 9 974. Gerundet: 5 000 · 2 = 10 000. Unterschied: 26 €.", "form": "lueckenweg", "zaehlt": "nein", "r": 5830}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du kennst die genaue Zahl 6 842. Für welchen Zweck darfst du sie runden?"}, "a": ["für die Geheimzahl einer Karte: 6 800", "für eine Zeitungsmeldung: „etwa 6 800 Zuschauer“", "für die Kasse: 6 800 € genau so buchen", "für die Hausnummer: Haus 6 800"], "o": {"index": 1}, "h": "Frage: Reicht „ungefähr“ oder muss es genau stimmen?", "w": "Runden ist erlaubt, wenn „ungefähr“ reicht, wie bei einer Meldung. Nummern, Geheimzahlen und ein Betrag, der gebucht wird, müssen genau stimmen.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5831}, {"l": "runden_sinnvoll", "t": "runden_sinnvoll", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Fest kommen 238 Gäste. Jeder Gast bekommt einen Becher. Becher gibt es nur in Packungen zu je 50 Stück. Wie viele Packungen musst du mindestens kaufen?"}, "o": {"wert": 5}, "h": "Eine Packung mehr ist besser als zu wenig Becher. Hier wird immer aufgerundet.", "w": "238 : 50 = 4 Rest 38. Vier Packungen reichen nicht, es sind 5 Packungen.", "form": "anwenden", "zaehlt": "ja", "r": 5832}, {"l": "unendlich", "t": "unendlich", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim sagt: „Es gibt eine größte natürliche Zahl.“ Er begründet. Zeile 1: Die größte Zahl mit 3 Ziffern ist 999. Zeile 2: Mit 4 Ziffern ist die größte Zahl 9 999. Sie ist größer. Zeile 3: Irgendwo kommt eine Zahl, die keinen Nachfolger mehr hat. Sie ist die größte. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Kannst du zu jeder Zahl 1 dazuzählen?", "w": "Zu jeder Zahl gibt es einen Nachfolger (+ 1). Darum gibt es keine größte natürliche Zahl.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5833}, {"l": "unendlich", "t": "unendlich", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl hat den Nachfolger 1 000 000. Wie heißt der Vorgänger dieser Zahl?"}, "o": {"wert": 999998}, "h": "Gehe von 1 000 000 aus zwei Schritte zurück.", "w": "Die Zahl selbst ist 999 999 (Vorgänger von 1 000 000). Ihr Vorgänger ist 999 998.", "form": "umkehren", "zaehlt": "ja", "r": 5834}, {"l": "unendlich", "t": "unendlich", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zähler am Eingang eines Parks zählt jeden Besucher mit einer Ziffernanzeige. Er soll bis zur Zahl 1 000 000 zählen können. Wie viele Ziffernfelder braucht die Anzeige mindestens?"}, "o": {"wert": 7}, "h": "Schreibe 1 000 000 auf und zähle die Ziffern.", "w": "1 000 000 hat eine 1 und sechs Nullen: 7 Ziffern. Mit 6 Feldern würde nach 999 999 Schluss sein.", "form": "anwenden", "zaehlt": "ja", "r": 5835}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "MCMXLIV wird zerlegt. M = 1 000. CM = 1 000 − 100 = ①. XL = 50 − 10 = ②. IV = 5 − 1 = ③. Die Zahl ist die Summe 1 000 + ① + ② + ③ = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [900, 40, 4, 1944]}, "h": "Ein kleineres Zeichen vor einem größeren wird abgezogen.", "w": "CM = 900, XL = 40, IV = 4. Summe: 1 000 + 900 + 40 + 4 = 1 944.", "form": "lueckenweg", "zaehlt": "nein", "r": 5836}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 2, "g": "darstellung", "y": "text", "f": {"text": "Die Tafel zeigt Tausender, Hunderter, Zehner und Einer einer Zahl. Schreibe die Zahl mit römischen Zeichen.", "grafik": {"typ": "tabelle", "kopf": ["T", "H", "Z", "E"], "zeilen": [["1", "4", "9", "3"]]}}, "o": {"text": "MCDXCIII"}, "h": "Schreibe jeden Teil einzeln: 1 000, 400, 90, 3. Dann hintereinander.", "w": "1 000 = M, 400 = CD, 90 = XC, 3 = III. Zusammen: MCDXCIII.", "form": "bruecke", "zaehlt": "ja", "r": 5837}, {"l": "roemisch_schreiben", "t": "roemisch_schreiben", "p": "uebung", "s": 2, "g": "umkehr", "y": "text", "f": {"text": "Der Nachfolger einer Zahl ist XL. Schreibe die Zahl mit römischen Zeichen."}, "o": {"text": "XXXIX"}, "h": "Wie viel ist XL? Gehe einen Schritt zurück.", "w": "XL ist 40. Der Vorgänger ist 39 = 30 + 9 = XXX + IX = XXXIX.", "form": "umkehren", "zaehlt": "ja", "r": 5838}, {"l": "roemisch_system", "t": "roemisch_system", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim vergleicht die römischen Zahlen IX und XI. Zeile 1: Bei IX steht das kleinere Zeichen I vor dem größeren X. Ich addiere trotzdem: 10 + 1 = 11. Zeile 2: Bei XI steht das I hinter dem X: 10 + 1 = 11. Zeile 3: Also haben IX und XI den gleichen Wert, nämlich 11. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Steht das I bei IX vor oder hinter dem X? Was bedeutet das?", "w": "Steht ein kleineres Zeichen vor einem größeren, wird es abgezogen: IX = 10 − 1 = 9. XI = 10 + 1 = 11.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5839}, {"l": "roemisch_system", "t": "roemisch_system", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie viel ist MCMLXXXIV? Weg A: von links nach rechts lesen und jedes Zeichen zählen; ein kleineres Zeichen vor einem größeren wird abgezogen. Weg B: in eine Stellentafel eintragen: M zu den Tausendern, CM zu den Hundertern, LXXX zu den Zehnern, IV zu den Einern."}, "o": {"wert": 1984}, "h": "Beide Wege geben dieselbe Zahl.", "w": "Weg A: 1 000 + 900 + 80 + 4 = 1 984. Weg B: Tausender 1, Hunderter 9, Zehner 8, Einer 4: 1 984.", "form": "zwei_wege", "zaehlt": "ja", "r": 5840}, {"l": "roemisch_system", "t": "roemisch_system", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Über einer Haustür steht das Baujahr MDCCCLXXV. Wie viele Jahre ist das Haus im Jahr 2026 alt?"}, "o": {"wert": 151}, "h": "Lies zuerst das Baujahr in normalen Ziffern.", "w": "MDCCCLXXV = 1 000 + 500 + 300 + 70 + 5 = 1 875. 2 026 − 1 875 = 151 Jahre.", "form": "anwenden", "zaehlt": "ja", "r": 5841}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Zweierzahl 1101 hat die Stellenwerte 8, 4, 2 und 1. Gerechnet: 1 · 8 + 1 · 4 + 0 · 2 + 1 · 1 = ①. Die Zweierzahl 10010 hat die Stellenwerte 16, 8, 4, 2 und 1. Ebenso gerechnet ist sie ②. Die zweite Zahl ist um ② − ① = ③ größer.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 18, 5]}, "h": "Nur die Stellenwerte mit einer 1 darunter werden addiert.", "w": "1101: 8 + 4 + 1 = 13. 10010: 16 + 2 = 18. 18 − 13 = 5.", "form": "lueckenweg", "zaehlt": "nein", "r": 5842}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tafel zeigt die Stellenwerte einer Zweierzahl und ihre Ziffern. Welche normale Zahl ist das?", "grafik": {"typ": "tabelle", "kopf": ["16", "8", "4", "2", "1"], "zeilen": [["1", "0", "1", "1", "0"]]}}, "o": {"wert": 22}, "h": "Addiere nur die Stellenwerte, unter denen eine 1 steht.", "w": "Unter 16, 4 und 2 steht eine 1: 16 + 4 + 2 = 22.", "form": "bruecke", "zaehlt": "ja", "r": 5843}, {"l": "dualsystem", "t": "dualsystem", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Lichtband hat fünf Lampen für die Stellenwerte 16, 8, 4, 2 und 1. Die Lampen sind von links nach rechts so geordnet. Es leuchten die erste, die dritte und die fünfte Lampe. So zeigt das Band, wie viele Gäste im Saal sind. Dann kommen noch 9 Gäste. Wie viele Gäste sind es dann?"}, "o": {"wert": 30}, "h": "Die leuchtenden Lampen sind die Einsen. Erst die Zahl auf dem Band, dann addieren.", "w": "Es leuchten die Lampen für 16, 4 und 1: 21 Gäste. 21 + 9 = 30.", "form": "anwenden", "zaehlt": "ja", "r": 5844}]$auf$::jsonb),
    (28, 'messen.koerper_darstellung', 589, 18, $auf$[{"l": "prisma", "t": "prisma", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Prisma hat ein Sechseck als Grundfläche. Grund- und Deckfläche haben je 6 Ecken, zusammen ①. An jeder Ecke treffen sich 3 Kanten, und jede Kante hat 2 Ecken. Die Zahl der Kanten ist deshalb ① · 3 : 2 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 18]}, "h": "Zähle die Ecken von Grund- und Deckfläche zusammen.", "w": "Ecken: 6 + 6 = 12. Kanten: 12 · 3 : 2 = 18. Das ist auch 3 · 6.", "form": "lueckenweg", "zaehlt": "nein", "r": 5590}, {"l": "prisma", "t": "prisma", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Prisma hat ein Siebeneck als Grundfläche. Wie viele Kanten hat es? Weg A zählt die Ecken des Prismas. An jeder Ecke treffen sich 3 Kanten, und jede Kante hat 2 Ecken. Weg B zählt die Kanten der Grundfläche, die der Deckfläche und die Seitenkanten einzeln."}, "o": {"wert": 21}, "h": "Beide Wege geben dieselbe Zahl.", "w": "Weg A: Ecken 7 + 7 = 14. Kanten 14 · 3 : 2 = 21. Weg B: 7 + 7 + 7 = 21 Kanten.", "form": "zwei_wege", "zaehlt": "ja", "r": 5591}, {"l": "prisma", "t": "prisma", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schachtel hat die Form eines Prismas mit einem Fünfeck als Grundfläche. Auf jede Fläche, auch Grund- und Deckfläche, kommt ein Aufkleber. Eine Packung enthält 15 Aufkleber. Wie viele Packungen braucht man mindestens für 6 Schachteln?"}, "o": {"wert": 3}, "h": "Wie viele Flächen hat das Prisma? Danach: Mit angebrochenen Packungen kommst du nicht aus.", "w": "Flächen: 5 Seitenflächen + 2 = 7. 6 Schachteln: 42 Aufkleber. 42 : 15 = 2,8, also 3 Packungen.", "form": "anwenden", "zaehlt": "ja", "r": 5592}, {"l": "netz", "t": "netz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Quader ist 6 cm lang, 2 cm breit und 3 cm hoch. Kim berechnet die Fläche seines Netzes. Zeile 1: Das Netz besteht aus 6 Rechtecken, je zwei gleiche. Zeile 2: Die drei verschiedenen Rechtecke haben die Flächen 6 · 2 = 12, 6 · 3 = 18 und 2 · 3 = 6 cm². Zeile 3: Ich zähle jede der drei Flächen nur einmal: 12 + 18 + 6 = 36 cm². Zeile 4: Das Netz hat 36 cm² Fläche. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Wie viele Rechtecke hat das Netz? Wie oft kommt jede Fläche vor?", "w": "Jedes der drei Rechtecke kommt zweimal vor: 2 · (12 + 18 + 6) = 72 cm².", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5593}, {"l": "netz", "t": "netz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Würfelnetz besteht aus 6 gleichen Quadraten und hat zusammen 150 cm² Fläche. Wie lang ist eine Würfelkante in cm?"}, "o": {"wert": 5, "einheit": "cm"}, "h": "Wie groß ist ein einzelnes Quadrat? Welche Zahl mal sich selbst gibt diese Fläche?", "w": "150 : 6 = 25 cm² für ein Quadrat. 5 · 5 = 25, also ist die Kante 5 cm lang.", "form": "umkehren", "zaehlt": "ja", "r": 5594}, {"l": "netz", "t": "netz", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle beschreibt die Rechtecke im Netz eines Quaders. Wie groß ist die ganze Netzfläche in cm²?", "grafik": {"typ": "tabelle", "kopf": ["Fläche", "Maße in cm", "Anzahl"], "zeilen": [["Boden", "5 × 3", "2"], ["Vorderseite", "5 × 4", "2"], ["Seite", "3 × 4", "2"]]}}, "o": {"wert": 94, "einheit": "cm²"}, "h": "Rechne erst jede Rechteckfläche, dann mal Anzahl, dann alles addieren.", "w": "Boden und Deckel: 2 · 15 = 30. Vorder- und Rückseite: 2 · 20 = 40. Seiten: 2 · 12 = 24. Zusammen 94 cm².", "form": "bruecke", "zaehlt": "ja", "r": 5595}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Eine zylindrische Dose ist 12 cm hoch. Der Umfang ihrer Grundfläche ist 30 cm. Der Mantel ist ein Rechteck: Länge = Umfang, Breite = Höhe. Die Mantelfläche einer Dose ist 30 · 12 = ①. Fünf solche Dosen sollen nur außen am Mantel gestrichen werden, ohne Boden und Deckel: Mantelfläche aller fünf Dosen ① · 5 = ②. Ein Eimer Farbe reicht für 600 cm². Man braucht ② : 600 = ③ Eimer.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [360, 1800, 3]}, "h": "Der Mantel ist so lang wie der Umfang, nicht wie der Durchmesser.", "w": "30 · 12 = 360 cm². 360 · 5 = 1 800 cm². 1 800 : 600 = 3 Eimer.", "form": "lueckenweg", "zaehlt": "nein", "r": 5596}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Das Mantel-Rechteck einer Dose hat die Fläche 420 cm². Der Umfang der Grundfläche beträgt 28 cm. Wie hoch ist die Dose?"}, "o": {"wert": 15, "einheit": "cm"}, "h": "Fläche = Umfang mal Höhe. Welche Rechnung macht das Malnehmen rückgängig?", "w": "420 : 28 = 15. Probe: 28 · 15 = 420. Die Dose ist 15 cm hoch.", "form": "umkehren", "zaehlt": "ja", "r": 5597}, {"l": "zylinder", "t": "zylinder", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für jede Dose braucht man ein Etikett: ein Rechteck, 24 cm lang und 10 cm hoch. Du hast ein Papierband, das 10 cm breit und 1 000 cm lang ist. Die Etiketten werden nacheinander in einer Reihe aus dem Band geschnitten, jedes mit der 24-cm-Seite längs des Bandes. Wie viele ganze Etiketten bekommst du aus dem Band?"}, "o": {"wert": 41}, "h": "Das Band ist so breit wie ein Etikett hoch. Wie oft passt die Länge 24 cm in 1 000 cm? Ein Rest zählt nicht.", "w": "1 000 : 24 = 41 Rest 16. Es passen 41 ganze Etiketten. Für ein 42. Etikett fehlen 8 cm.", "form": "anwenden", "zaehlt": "ja", "r": 5598}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Quader ist 8 cm breit, 6 cm hoch und 10 cm tief. Im Schrägbild wird nur die Tiefe halb so lang gezeichnet. Wie lang sind alle zwölf Kanten des Schrägbilds zusammen? Weg A addiert die vier Kanten jeder Richtung, so wie sie gezeichnet werden. Weg B rechnet zuerst alle zwölf Kanten des echten Quaders und zieht dann ab, was die vier Tiefenkanten im Schrägbild kürzer sind."}, "o": {"wert": 76, "einheit": "cm"}, "h": "Die vier Kanten jeder Richtung sind gleich lang.", "w": "Weg A: Gezeichnet werden 8 cm, 6 cm und 5 cm. 32 + 24 + 20 = 76. Weg B: Der echte Quader hat 4 · 24 = 96. Die vier Tiefenkanten sind je 5 cm kürzer: 96 − 20 = 76.", "form": "zwei_wege", "zaehlt": "ja", "r": 5599}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle zeigt die wahren Maße eines Quaders. Im Schrägbild wird nur die Kante nach hinten halbiert. Welche Längen zeichnest du für Breite, Höhe und Tiefe?", "grafik": {"typ": "tabelle", "kopf": ["", "Breite", "Höhe", "Tiefe"], "zeilen": [["wahr", "8 cm", "6 cm", "10 cm"]]}}, "a": ["4 cm, 3 cm, 5 cm", "8 cm, 6 cm, 10 cm", "8 cm, 3 cm, 10 cm", "8 cm, 6 cm, 5 cm"], "o": {"index": 3}, "h": "Nur eine Richtung wird verkürzt. Welche?", "w": "Breite und Höhe liegen vorn und bleiben in wahrer Größe. Nur die Tiefe nach hinten wird halbiert: 10 : 2 = 5 cm.", "form": "bruecke", "zaehlt": "ja", "r": 5600}, {"l": "schraegbild", "t": "schraegbild", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Du zeichnest ein Schrägbild eines Schranks. Er ist 90 cm breit, 200 cm hoch und 60 cm tief. Dein Maßstab ist 1 : 10, in der Zeichnung steht also 1 cm für 10 cm. Die Tiefe wird zusätzlich halb so lang gezeichnet. Wie viele Zentimeter lang zeichnest du die Kante nach hinten?"}, "o": {"wert": 3, "einheit": "cm"}, "h": "Erst den Maßstab anwenden, dann die Tiefe halbieren.", "w": "Im Maßstab 1 : 10 sind 60 cm nur 6 cm. Nach hinten wird halbiert: 3 cm.", "form": "anwenden", "zaehlt": "ja", "r": 5601}, {"l": "ansichten", "t": "ansichten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim beschreibt die drei Ansichten einer stehenden zylinderförmigen Dose. Zeile 1: Von vorn sieht man ein Rechteck. Zeile 2: Von der Seite sieht man ebenfalls ein Rechteck. Zeile 3: Von oben sieht man nur den Deckel. Zeile 4: Der Deckel ist ein Rechteck. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Welche Form hat der Deckel einer zylinderförmigen Dose?", "w": "Der Deckel ist ein Kreis. Von oben sieht man deshalb einen Kreis.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5602}, {"l": "ansichten", "t": "ansichten", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Ein Körper sieht von vorn aus wie ein Rechteck, von der Seite auch wie ein Rechteck und von oben wie ein Kreis. Welcher Körper ist es?"}, "a": ["ein Quader, denn er hat überall Rechtecke", "ein stehender Zylinder: oben ein Kreis, vorn und von der Seite je ein Rechteck", "ein Kegel, denn er hat einen Kreis", "eine Kugel, denn sie ist rund"], "o": {"index": 1}, "h": "Prüfe jeden Körper mit allen drei Ansichten.", "w": "Nur beim Zylinder passt alles: vorn und seitlich ein Rechteck, oben ein Kreis.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5603}, {"l": "ansichten", "t": "ansichten", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Architekt zeichnet ein Haus, das die Form eines Quaders hat: 10 m breit, 6 m tief und 5 m hoch. Wie groß ist die Fläche der Ansicht von oben in m²?"}, "o": {"wert": 60, "einheit": "m²"}, "h": "Von oben sieht man Breite und Tiefe, nicht die Höhe.", "w": "Die Ansicht von oben ist ein Rechteck mit 10 m und 6 m: 10 · 6 = 60 m².", "form": "anwenden", "zaehlt": "ja", "r": 5604}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Kim behauptet: „Jeder Körper mit lauter ebenen Flächen ist ein Prisma.“ Wie widerlegst du das am besten?"}, "a": ["Mit vielen Prismen, die ebene Flächen haben", "Mit einem Gegenbeispiel: Eine Pyramide hat lauter ebene Flächen, aber keine zwei parallelen Grundflächen", "Mit einer Kugel, denn sie hat keine ebenen Flächen", "Mit dem Zählen der Kanten eines Würfels"], "o": {"index": 1}, "h": "Ein einziges Beispiel, das die Behauptung nicht erfüllt, genügt.", "w": "Die Pyramide hat nur ebene Flächen. Sie ist aber kein Prisma, weil die zweite parallele Grundfläche fehlt.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5605}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Du baust ein Prisma aus Strohhalmen. Du brauchst genau 9 Halme als Kanten. Wie viele Ecken hat dann seine Grundfläche?"}, "o": {"wert": 3}, "h": "Ein Prisma mit einem n-Eck als Grundfläche hat 3 · n Kanten.", "w": "3 · n = 9, also n = 9 : 3 = 3. Die Grundfläche ist ein Dreieck.", "form": "umkehren", "zaehlt": "ja", "r": 5606}, {"l": "beurteilen", "t": "beurteilen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Schmuckkästchen hat die Form eines Prismas mit einem Siebeneck als Grundfläche. Wie viele Ecken, Kanten und Flächen hat es zusammen?"}, "o": {"wert": 44}, "h": "Ecken: 2n, Kanten: 3n, Flächen: n + 2. Dann alles addieren.", "w": "Ecken: 14. Kanten: 21. Flächen: 7 + 2 = 9. Zusammen 14 + 21 + 9 = 44.", "form": "anwenden", "zaehlt": "ja", "r": 5607}]$auf$::jsonb),
    (39, 'zahlen.ganz', 789, 33, $auf$[{"l": "deuten", "t": "verstehen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Es sind vier Grad unter null. Das schreibt man als Zahl mit Vorzeichen. Dann wird es 7 Grad wärmer: Die neue Temperatur ist ① °C. Danach sinkt sie von ① °C um 9 Grad: Sie ist dann ② °C.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, -6]}, "h": "Unter null schreibst du ein Minus vor die Zahl.", "w": "Vier Grad unter null sind −4 °C. −4 + 7 = 3 °C. 3 − 9 = −6 °C.", "form": "lueckenweg", "zaehlt": "nein", "r": 5790}, {"l": "deuten", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Temperatur an einem Wintertag. Um wie viele Grad ist es um 12 Uhr wärmer als um 6 Uhr?", "grafik": {"typ": "tabelle", "kopf": ["Uhrzeit", "6 Uhr", "12 Uhr", "18 Uhr"], "zeilen": [["Grad", "−5", "3", "−2"]]}}, "o": {"wert": 8}, "h": "Wie weit ist es von −5 bis 0, und wie weit von 0 bis 3?", "w": "Von −5 bis 0 sind es 5 Grad, von 0 bis 3 noch 3 Grad. Zusammen 8 Grad.", "form": "bruecke", "zaehlt": "ja", "r": 5791}, {"l": "deuten", "t": "verstehen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einem Hochhaus ist das zweite Kellergeschoss die Etage −2. Das Erdgeschoss ist die Etage 0. Ein Aufzug fährt vom Parkdeck in Etage −3 bis in die Etage 4. Wie viele Etagen fährt er?"}, "o": {"wert": 7}, "h": "Zähle von −3 bis 0 und dann von 0 bis 4.", "w": "Von −3 bis 0 sind es 3 Etagen, von 0 bis 4 noch 4. Zusammen 7 Etagen.", "form": "anwenden", "zaehlt": "ja", "r": 5792}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Zahlengerade geht von −10 bis 10 und hat 10 Abschnitte. Der Punkt P liegt 3 Abschnitte links von 0. Kim bestimmt P. Zeile 1: Ein Abschnitt ist 10 : 10 = 1 wert. Zeile 2: P liegt 3 Abschnitte links von 0: 3 · 1 = 3, links also −3. Zeile 3: Also ist P = −3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie lang ist der dargestellte Abschnitt von −10 bis 10? Nicht nur die rechte Seite zählt.", "w": "Der dargestellte Abschnitt reicht von −10 bis 10 und ist 20 lang. Ein Abschnitt ist 20 : 10 = 2 wert. 3 Abschnitte links von 0 sind −6.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5793}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Punkt A liegt bei −7, der Punkt B bei 5. Weg A: zähle von −7 bis 0 und von 0 bis 5. Weg B: rechne 5 − (−7). Wie weit sind A und B voneinander entfernt?"}, "o": {"wert": 12}, "h": "Beide Wege geben dieselbe Zahl.", "w": "Weg A: 7 + 5 = 12. Weg B: 5 − (−7) = 5 + 7 = 12.", "form": "zwei_wege", "zaehlt": "ja", "r": 5794}, {"l": "zahlengerade", "t": "verstehen", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Zahlengerade zeigt die Punkte A und B. Wie viele Einheiten liegt B rechts von A?", "grafik": {"typ": "zahlenstrahl", "start": -10, "ende": 10, "abschnitte": 20, "punkte": [{"wert": -7, "name": "A"}, {"wert": 4, "name": "B"}], "beschriftet": "alle"}}, "o": {"wert": 11}, "h": "Lies zuerst die beiden Zahlen ab.", "w": "A liegt bei −7, B bei 4. Von −7 bis 0 sind es 7, von 0 bis 4 noch 4: zusammen 11.", "form": "bruecke", "zaehlt": "ja", "r": 5795}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vergleiche −15 und −6. Die Zahl −15 liegt weiter links, sie ist kleiner. Der Unterschied: (−6) − (−15) = ①. Starte bei −15, gehe ① Schritte nach rechts und dann noch 4 Schritte weiter. Du landest bei ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, -2]}, "h": "Minus minus heißt plus. Rechts ist größer.", "w": "(−6) − (−15) = −6 + 15 = 9. −15 + 9 = −6, dann −6 + 4 = −2.", "form": "lueckenweg", "zaehlt": "nein", "r": 5796}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl ist um 4 größer als die gesuchte Zahl. Sie ist 1. Wie heißt die gesuchte Zahl?"}, "o": {"wert": -3}, "h": "Gehe von 1 vier Schritte nach links.", "w": "Gesucht ist die Zahl, die 4 kleiner ist als 1: 1 − 4 = −3.", "form": "umkehren", "zaehlt": "ja", "r": 5797}, {"l": "ordnen", "t": "ordnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "An drei Morgen wurden diese Temperaturen gemessen: −4 °C, −9 °C und 2 °C. Wie viel Grad wärmer ist der wärmste Morgen als der kälteste?"}, "o": {"wert": 11, "einheit": "Grad"}, "h": "Ordne zuerst. Der kälteste Morgen liegt am weitesten links.", "w": "Wärmster: 2 °C, kältester: −9 °C. Unterschied: 2 − (−9) = 11 Grad.", "form": "anwenden", "zaehlt": "ja", "r": 5798}, {"l": "betrag", "t": "ordnen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim sucht alle ganzen Zahlen, deren Betrag 5 ist. Zeile 1: |5| = 5. Zeile 2: Eine Zahl links von 0 kann nicht den Betrag 5 haben. Zeile 3: Es gibt nur eine solche Zahl, nämlich 5. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Der Betrag ist der Abstand zu 0. Gibt es auch links von 0 eine Zahl mit diesem Abstand?", "w": "Der Betrag ist der Abstand zu 0. Auch −5 hat den Abstand 5. Es gibt zwei solche Zahlen: 5 und −5.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5799}, {"l": "betrag", "t": "ordnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zwei Zahlen sind Gegenzahlen und liegen 18 Einheiten auseinander. Wie heißt die negative der beiden Zahlen?"}, "o": {"wert": -9}, "h": "Gegenzahlen liegen gleich weit von 0 entfernt, auf beiden Seiten.", "w": "Die 18 Einheiten teilen sich auf beide Seiten von 0: 18 : 2 = 9. Die negative Zahl ist −9.", "form": "umkehren", "zaehlt": "ja", "r": 5800}, {"l": "betrag", "t": "ordnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Taucher ist 14 m unter der Wasseroberfläche (−14 m). Ein Kranhaken hängt senkrecht über ihm, 6 m über dem Wasser. Wie groß ist der Höhenunterschied zwischen Taucher und Haken?"}, "o": {"wert": 20, "einheit": "m"}, "h": "Ein Höhenunterschied ist ein Abstand: Er darf nicht negativ sein.", "w": "Vom Taucher bis zur Oberfläche sind es 14 m, von dort bis zum Haken 6 m. Zusammen 20 m.", "form": "anwenden", "zaehlt": "ja", "r": 5801}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schriftlich 2 746 + 3 585. Einer: 6 + 5 = 11. Ich schreibe die Einerziffer hin und merke den Übertrag. Zehner: 4 + 8 und der gemerkte Übertrag ergeben ①. Ich schreibe die Einerziffer von ① hin und merke den Übertrag ②. Hunderter: 7 + 5 + ② = ③. Ich schreibe die Einerziffer von ③ hin und merke wieder den Übertrag. Tausender: 2 + 3 und der Übertrag ergeben 6. Das Ergebnis liest du von links: erst die 6 und danach die Einerziffer von ③ und danach die Einerziffer von ① und zuletzt die Einerziffer von 11. Es ist ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 1, 13, 6331]}, "h": "Der Übertrag ist die Zehnerziffer der Spaltensumme.", "w": "Einer: 11, Übertrag 1. Zehner: 4 + 8 + 1 = 13, Übertrag 1. Hunderter: 7 + 5 + 1 = 13, Übertrag 1. Tausender: 2 + 3 + 1 = 6. Ergebnis: 6 331.", "form": "lueckenweg", "zaehlt": "nein", "r": 5802}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 5 000 − 1 876. Weg A: schriftlich subtrahieren mit Tauschen. Weg B: erst 5 000 − 2 000 = 3 000, dann den zu viel abgezogenen Teil wieder addieren. Wie groß ist das Ergebnis?"}, "o": {"wert": 3124}, "h": "Wie viel hast du bei Weg B zu viel abgezogen?", "w": "Weg A: 5 000 − 1 876 = 3 124. Weg B: 2 000 − 1 876 = 124 zu viel. 3 000 + 124 = 3 124.", "form": "zwei_wege", "zaehlt": "ja", "r": 5803}, {"l": "schriftlich_plus_minus", "t": "schriftlich", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Flughafen hatte im Mai 1 245 780 Fluggäste und im Juni 1 398 650 Fluggäste. Wie viele Fluggäste kamen im Juni mehr?"}, "o": {"wert": 152870}, "h": "Rechne schriftlich minus und achte auf das Tauschen.", "w": "1 398 650 − 1 245 780 = 152 870 Fluggäste mehr.", "form": "anwenden", "zaehlt": "ja", "r": 5804}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet (−7) + 4. Zeile 1: Die 4 ist positiv. Wer sie addiert, geht auf der Zahlengeraden nach links. Zeile 2: Ich starte bei −7 und gehe 4 Schritte nach links. Zeile 3: Ich lande bei −11. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "In welche Richtung gehst du, wenn du eine positive Zahl addierst?", "w": "Hier wird +4 addiert: vier Schritte nach rechts. Die Richtung hängt vom Vorzeichen des Summanden ab: positiv nach rechts, negativ nach links. Von −7 vier Schritte nach rechts: −7 + 4 = −3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5805}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zu einer Zahl wird 9 addiert. Das Ergebnis ist −2. Wie heißt die Zahl?"}, "o": {"wert": -11}, "h": "Kehre die Addition um: minus 9.", "w": "−2 − 9 = −11. Probe: (−11) + 9 = −2.", "form": "umkehren", "zaehlt": "ja", "r": 5806}, {"l": "addieren", "t": "addieren", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Der Sprung auf der Zahlengeraden beginnt bei −6 und endet bei 2. Welche Rechnung gehört dazu?", "grafik": {"typ": "zahlenstrahl", "start": -10, "ende": 10, "abschnitte": 20, "punkte": [{"wert": -6, "name": "Start"}, {"wert": 2, "name": "Ziel"}], "boegen": [{"von": -6, "bis": 2, "name": "Sprung"}], "beschriftet": "alle"}}, "a": ["(−6) − 8 = −14", "6 + 8 = 14", "(−6) + 2 = −4", "(−6) + 8 = 2"], "o": {"index": 3}, "h": "Wie viele Schritte nach rechts sind es von −6 bis 2?", "w": "Von −6 bis 0 sind es 6 Schritte, von 0 bis 2 noch 2: zusammen 8 Schritte nach rechts. (−6) + 8 = 2.", "form": "bruecke", "zaehlt": "ja", "r": 5807}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Minus eine Zahl heißt: plus die Gegenzahl. 5 − 13 = ①. Dann ① − (−6) = ②. Dann ② − (−11) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-8, -2, 9]}, "h": "Minus minus wird plus.", "w": "5 − 13 = −8. −8 + 6 = −2. −2 + 11 = 9.", "form": "lueckenweg", "zaehlt": "nein", "r": 5808}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 4 − (−9) − 6. Weg A: von links nach rechts. Weg B: erst 4 − 6 = −2, dann (−2) − (−9). Wie groß ist das Ergebnis?"}, "o": {"wert": 7}, "h": "Minus minus ist plus. Beide Wege geben dieselbe Zahl.", "w": "Weg A: 4 + 9 = 13, 13 − 6 = 7. Weg B: −2 + 9 = 7.", "form": "zwei_wege", "zaehlt": "ja", "r": 5809}, {"l": "subtrahieren", "t": "subtrahieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Taucher ist bei −18 m. Er steigt auf −7 m. Um wie viele Meter ist er gestiegen? Rechne Ende minus Anfang."}, "o": {"wert": 11, "einheit": "m"}, "h": "Ende minus Anfang, also (−7) − (−18). Minus minus ist plus.", "w": "(−7) − (−18) = −7 + 18 = 11. Er ist 11 m gestiegen.", "form": "anwenden", "zaehlt": "ja", "r": 5810}, {"l": "umkehraufgabe", "t": "gleichungen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim löst x + 7 = −3. Zeile 1: Die Umkehraufgabe von „plus 7“ ist „minus 7“. Zeile 2: Also ist x = −3 − 7. Zeile 3: Minus und Minus ergibt Plus, also rechne ich −3 + 7. Zeile 4: Also ist x = 4. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Hier steht nur ein Minus vor der 7, die −3 ist negativ. Gilt „minus und minus ergibt plus“?", "w": "Hier steht kein Doppelminus: −3 − 7 heißt von −3 sieben Schritte nach links: −10. Probe: (−10) + 7 = −3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5811}, {"l": "umkehraufgabe", "t": "gleichungen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du löst x − 5 = −8. Welcher Weg ist richtig?"}, "a": ["x = −8 + 5 = −3", "x = −8 − 5 = −13", "x = 8 + 5 = 13", "x = (−8) : 5"], "o": {"index": 0}, "h": "Welche Rechnung macht „minus 5“ rückgängig?", "w": "Minus 5 macht man mit plus 5 rückgängig: x = −8 + 5 = −3. Probe: (−3) − 5 = −8.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5812}, {"l": "umkehraufgabe", "t": "gleichungen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Morgens sind es 5 Grad unter null. Bis mittags steigt die Temperatur um einige Grad. Mittags zeigt das Thermometer 6 °C. Um wie viele Grad ist die Temperatur gestiegen?"}, "o": {"wert": 11, "einheit": "Grad"}, "h": "Gesucht ist x in: −5 + x = 6. Kehre um.", "w": "x = 6 − (−5) = 6 + 5 = 11. Probe: −5 + 11 = 6.", "form": "anwenden", "zaehlt": "ja", "r": 5813}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Rechne −4 + 9 − (−3) − 10. Wer eine negative Zahl abzieht, addiert ihre Gegenzahl. Sammle alles, was dazukommt: die 9 und die Gegenzahl der abgezogenen Zahl ergeben zusammen ①. Sammle alles, was abgeht: die 4 und die 10 ergeben zusammen ②. Ergebnis: ① − ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [12, 14, -2]}, "h": "Sammle erst alle Plus-Zahlen, dann alle Minus-Zahlen.", "w": "Plus: 9 + 3 = 12. Minus: 4 + 10 = 14. 12 − 14 = −2.", "form": "lueckenweg", "zaehlt": "nein", "r": 5814}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 8 − (−5) + (−12) − 3. Weg A: von links nach rechts. Weg B: erst die Klammern auflösen zu 8 + 5 − 12 − 3. Wie groß ist das Ergebnis?"}, "o": {"wert": -2}, "h": "Beide Wege geben dieselbe Zahl.", "w": "Weg A: 8 + 5 = 13, 13 − 12 = 1, 1 − 3 = −2. Weg B: 13 − 15 = −2.", "form": "zwei_wege", "zaehlt": "ja", "r": 5815}, {"l": "ketten", "t": "verbinden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Dein Kontostand ist −20 €. Dann kommen 85 € Taschengeld dazu, 30 € werden abgebucht, 15 € werden gutgeschrieben und 40 € werden abgebucht. Wie hoch ist der Kontostand danach?"}, "o": {"wert": 10, "einheit": "€"}, "h": "Sammle alles, was dazukommt, und alles, was abgeht.", "w": "Dazu: 85 + 15 = 100. Weg: 20 + 30 + 40 = 90. 100 − 90 = 10 €.", "form": "anwenden", "zaehlt": "ja", "r": 5816}, {"l": "verstehen", "t": "begruenden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim prüft die Aussage: „Wenn man etwas abzieht, wird das Ergebnis immer kleiner.“ Zeile 1: Beispiel: 10 − 4 = 6. Das ist kleiner als 10. Zeile 2: Noch ein Beispiel: 7 − 2 = 5. Das ist kleiner als 7. Zeile 3: Beide Beispiele stimmen. Zeile 4: Weil zwei Beispiele stimmen, ist die Aussage bewiesen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Probiere eine negative Zahl zum Abziehen, zum Beispiel 10 − (−4).", "w": "Der Fehler steckt in Zeile 4: Zwei passende Beispiele beweisen keine Aussage für alle Zahlen. Ein einziges Gegenbeispiel widerlegt sie: 10 − (−4) = 14 ist größer als 10.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5817}, {"l": "verstehen", "t": "begruenden", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Du willst prüfen, ob die Aussage „a + b ist immer größer als a“ stimmt. Was ist der beste Weg?"}, "a": ["Viele Beispiele mit positiven Zahlen sammeln", "Nur den Fall b = 1 testen", "Ein Gegenbeispiel suchen, zum Beispiel mit negativem b: 5 + (−2) = 3", "So lange rechnen, bis es stimmt"], "o": {"index": 2}, "h": "Ein einziges Gegenbeispiel genügt, um eine Aussage zu widerlegen.", "w": "Mit b = −2: 5 + (−2) = 3 ist kleiner als 5. Die Aussage stimmt nicht immer.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5818}, {"l": "verstehen", "t": "begruenden", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Kim behauptet: „a − 7 ist immer negativ.“ Für welche kleinste Zahl a (a = 0, 1, 2, …) stimmt das nicht mehr?"}, "o": {"wert": 7}, "h": "Für welches a ist a − 7 gleich 0 oder größer?", "w": "Für a = 6 ist 6 − 7 = −1. Für a = 7 ist 7 − 7 = 0. Null ist nicht negativ. Das kleinste Gegenbeispiel ist a = 7.", "form": "umkehren", "zaehlt": "ja", "r": 5819}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Am Morgen sind es −6 °C. Bis mittags wird es 9 Grad wärmer: (−6) + 9 = ①. Am Abend wird es 5 Grad kälter: ① − 5 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, -2]}, "h": "Wärmer heißt plus, kälter heißt minus.", "w": "−6 + 9 = 3. 3 − 5 = −2. Am Abend sind es −2 °C.", "form": "lueckenweg", "zaehlt": "nein", "r": 5820}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Taucher steigt 6 m auf und ist danach bei −11 m. Bei welcher Höhe war er vorher?"}, "o": {"wert": -17, "einheit": "m"}, "h": "Kehre das Aufsteigen um: Er war tiefer.", "w": "Vorher war er 6 m tiefer: −11 − 6 = −17. Probe: −17 + 6 = −11.", "form": "umkehren", "zaehlt": "ja", "r": 5821}, {"l": "sach", "t": "verbinden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Hochhaus hat drei Kellergeschosse (−3, −2, −1). Ein Aufzug startet im untersten Kellergeschoss (−3). Er fährt 8 Etagen hinauf, dann 5 Etagen hinunter und dann 2 Etagen hinauf. In welcher Etage hält er?"}, "o": {"wert": 2}, "h": "Rechne Schritt für Schritt von der Startetage aus.", "w": "−3 + 8 = 5. 5 − 5 = 0. 0 + 2 = 2. Er hält in Etage 2.", "form": "anwenden", "zaehlt": "ja", "r": 5822}]$auf$::jsonb),
    (41, 'zahlen.potenzen_basis', 558, 21, $auf$[{"l": "schreibweise", "t": "begriff", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim schreibt 5 · 5 · 5 · 5 als Potenz und rechnet sie aus. Zeile 1: Die Basis ist 5. Sie kommt 4-mal als Faktor vor. Zeile 2: Als Potenz: 5⁴. Zeile 3: Ausgerechnet: 5⁴ = 5 · 4 = 20. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was sagt der Exponent: Wie oft kommt die Basis als Faktor vor?", "w": "5⁴ = 5 · 5 · 5 · 5 = 625. Der Exponent zählt die Faktoren, er wird nicht mit der Basis malgenommen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5559}, {"l": "schreibweise", "t": "begriff", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Zahl 3 kommt sechsmal als Faktor vor. Welche Schreibweise gehört dazu?"}, "a": ["6³", "3 · 6", "3 + 6", "3⁶"], "o": {"index": 3}, "h": "Die Basis ist die Zahl, die malgenommen wird. Der Exponent sagt, wie oft.", "w": "Sechs Faktoren 3: 3 · 3 · 3 · 3 · 3 · 3 = 3⁶ = 729. Die Potenz 6³ wäre 216.", "form": "bruecke", "zaehlt": "ja", "r": 5560}, {"l": "schreibweise", "t": "begriff", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Potenz hat die Basis 2 und den Wert 64. Welcher Exponent steht dort?"}, "o": {"wert": 6}, "h": "Multipliziere 2 · 2 · … so lange, bis du bei 64 bist, und zähle die Zweier.", "w": "2 · 2 = 4, · 2 = 8, 16, 32, 64: sechs Faktoren. Also 2⁶ = 64.", "form": "umkehren", "zaehlt": "ja", "r": 5561}, {"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest 3⁴ = 3 · 3 · 3 · 3 Schritt für Schritt. Erst 3 · 3 = ①. Dann ① · 3 = ②. Dann ② · 3 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 27, 81]}, "h": "Immer das letzte Ergebnis noch einmal mit 3 malnehmen.", "w": "3 · 3 = 9, 9 · 3 = 27, 27 · 3 = 81.", "form": "lueckenweg", "zaehlt": "nein", "r": 5562}, {"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 4³. Weg A: die Mal-Kette 4 · 4 · 4. Weg B: 4 ist 2 · 2, also ist 4³ gleich 2⁶. Rechne 2⁶ als Mal-Kette aus. Wie groß ist das Ergebnis?"}, "o": {"wert": 64}, "h": "Beide Wege geben dieselbe Zahl. 4³ ist nicht 4 · 3.", "w": "Weg A: 4 · 4 · 4 = 64. Weg B: 4³ = (2 · 2)³ = 2⁶ = 2 · 2 · 2 · 2 · 2 · 2 = 64.", "form": "zwei_wege", "zaehlt": "ja", "r": 5563}, {"l": "berechnen", "t": "berechnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Bakterienkultur verdoppelt sich jede Stunde. Am Anfang sind es 5 Bakterien. Wie viele Bakterien sind es nach 4 Stunden?"}, "o": {"wert": 80}, "h": "Nach jeder Stunde mal 2. Das sind 4 Verdopplungen.", "w": "2⁴ = 16. 5 · 16 = 80 Bakterien.", "form": "anwenden", "zaehlt": "ja", "r": 5564}, {"l": "quadrat", "t": "berechnen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim berechnet 13² und die Fläche eines Quadrats. Zeile 1: 13² heißt 13 · 2. Zeile 2: 13 · 2 = 26. Zeile 3: Ein Quadrat mit 13 cm Seitenlänge hat also 26 cm² Fläche. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie oft steht die 13 als Faktor da?", "w": "13² heißt 13 · 13 = 169. Ein Quadrat mit 13 cm Seite hat 169 cm² Fläche.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5565}, {"l": "quadrat", "t": "berechnen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Quadrat hat die Fläche 196 cm². Wie lang ist eine Seite in cm?"}, "o": {"wert": 14, "einheit": "cm"}, "h": "Welche Zahl mal sich selbst gibt 196? Probiere bei 10 und 15.", "w": "14 · 14 = 196. Die Seite ist 14 cm lang.", "form": "umkehren", "zaehlt": "ja", "r": 5566}, {"l": "quadrat", "t": "berechnen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratischer Spielplatz ist 18 m lang und 18 m breit. Er wird mit Platten zu je 1 m² ausgelegt. Wie viele Platten braucht man?"}, "o": {"wert": 324}, "h": "Fläche eines Quadrats: Seite mal Seite.", "w": "18² = 18 · 18 = 324. Es sind 324 Platten.", "form": "anwenden", "zaehlt": "ja", "r": 5567}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Beachte: 5³ ist nicht 3⁵. Es ist 5³ = 5 · 5 · 5 = ①. Es ist 3⁵ = 3 · 3 · 3 · 3 · 3 = ②. Der Unterschied ist ② − ① = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [125, 243, 118]}, "h": "Zähle die Faktoren: Der Exponent sagt, wie oft die Basis dasteht.", "w": "5³ = 125. 3⁵ = 243. 243 − 125 = 118.", "form": "lueckenweg", "zaehlt": "nein", "r": 5568}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Vergleiche 4³ und 3⁴. Weg A: beide als Mal-Kette ausrechnen (4 · 4 · 4 und 3 · 3 · 3 · 3). Weg B: 3⁴ als 9 · 9 und 4³ als 8 · 8 schreiben, denn 3⁴ = (3 · 3) · (3 · 3) und 4³ = 2⁶ = 2³ · 2³. Um wie viel ist 3⁴ größer als 4³?"}, "o": {"wert": 17}, "h": "Beide Wege geben dieselbe Zahl. Welcher Weg rechnet mit kleineren Zahlen?", "w": "Weg A: 4³ = 64 und 3⁴ = 81. Weg B: 8 · 8 = 64 und 9 · 9 = 81. 81 − 64 = 17.", "form": "zwei_wege", "zaehlt": "ja", "r": 5569}, {"l": "vertauschen", "t": "begriff", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Schloss A hat 5 Rädchen mit je 2 Symbolen. Seine Einstellungen zählt man mit 2⁵. Schloss B hat 2 Rädchen mit je 5 Symbolen. Seine Einstellungen zählt man mit 5². Wie viele Einstellungen hat Schloss A mehr als Schloss B?"}, "o": {"wert": 7}, "h": "Rechne beide Potenzen getrennt aus.", "w": "2⁵ = 32. 5² = 25. 32 − 25 = 7.", "form": "anwenden", "zaehlt": "ja", "r": 5570}, {"l": "zehner", "t": "zehner", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim schreibt 7 · 10⁴ als Zahl. Zeile 1: 10⁴ ist eine 1 mit vier Nullen: 10 000. Zeile 2: 7 · 10⁴ heißt: 7 mal 10 000. Zeile 3: Das ist die 7 mit vier Nullen dahinter. Zeile 4: Also ist 7 · 10⁴ = 700 000. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Zähle die Nullen in deiner Zahl und vergleiche mit dem Exponenten.", "w": "7 und vier Nullen sind 70 000, nicht 700 000.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5571}, {"l": "zehner", "t": "zehner", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welche Schreibweise ist gleich der Zahl 3 400 000?"}, "a": ["34 · 10⁶", "34 · 10⁵", "34 · 10⁴", "3 400 · 10⁵"], "o": {"index": 1}, "h": "Wie viele Nullen stehen hinter der 34?", "w": "3 400 000 = 34 und fünf Nullen = 34 · 10⁵.", "form": "bruecke", "zaehlt": "ja", "r": 5572}, {"l": "zehner", "t": "zehner", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Die Zahl 25 000 000 000 soll als 25 · 10ⁿ geschrieben werden. Welche Zahl ist n?"}, "o": {"wert": 9}, "h": "Zähle die Nullen hinter der 25.", "w": "25 000 000 000 hat hinter der 25 genau 9 Nullen. n = 9.", "form": "umkehren", "zaehlt": "ja", "r": 5573}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest (−2)⁴ = (−2) · (−2) · (−2) · (−2). Erst (−2) · (−2) = ①. Dann ① · (−2) = ②. Dann ② · (−2) = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, -8, 16]}, "h": "Gleiche Vorzeichen ergeben plus, verschiedene minus.", "w": "(−2) · (−2) = 4; 4 · (−2) = −8; (−8) · (−2) = 16. Gerader Exponent: Ergebnis positiv.", "form": "lueckenweg", "zaehlt": "nein", "r": 5574}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst −3² berechnen (ohne Klammer um die −3). Welcher Weg ist richtig?"}, "a": ["(−3) · (−3) = 9", "Erst 3² = 9, das Minus steht davor: −9", "−3 · 2 = −6", "−3 + 2 = −1"], "o": {"index": 1}, "h": "Zu welcher Zahl gehört der Exponent 2?", "w": "Der Exponent gehört nur zur 3. Erst 3² = 9, dann das Minus: −9. Mit Klammern wäre (−3)² = 9.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5575}, {"l": "negativ", "t": "negativ", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine negative Zahl hoch 3 ergibt −125. Wie heißt die Basis?"}, "o": {"wert": -5}, "h": "Welche Zahl ergibt als Produkt aus drei gleichen Faktoren 125? Dann das Vorzeichen.", "w": "(−5) · (−5) · (−5) = 25 · (−5) = −125. Bei ungeradem Exponent bleibt das Minus.", "form": "umkehren", "zaehlt": "ja", "r": 5576}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim faltet ein Blatt Papier 5-mal. Jedes Mal faltet er das ganze schon gefaltete Paket in der Mitte. Er will wissen, wie viele Lagen es dann sind. Zeile 1: Nach dem 1. Falten sind es 2 Lagen. Zeile 2: Bei jedem weiteren Falten kommen 2 Lagen dazu. Zeile 3: Nach dem 5. Falten sind es 2 + 2 · 4 = 10 Lagen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viele Lagen sind es nach dem 3. Falten? Nimm ein Blatt und falte.", "w": "Beim Falten verdoppelt sich die Zahl der Lagen: 2, 4, 8, 16, 32. Nach 5-mal sind es 2⁵ = 32 Lagen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5577}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Kettennachricht: In Runde 1 schickt eine Person sie an 3 Personen. In jeder weiteren Runde schickt jede Person, die sie in der Runde davor neu bekommen hat, sie an 3 weitere Personen. Niemand bekommt die Nachricht zweimal: Alle Empfänger sind neu und verschieden. Wie viele Personen bekommen die Nachricht in Runde 4 neu?"}, "o": {"wert": 81}, "h": "Runde 1: 3, Runde 2: 9. Jede Runde mal 3.", "w": "Runde 1: 3, Runde 2: 9, Runde 3: 27, Runde 4: 81. Das ist 3⁴.", "form": "anwenden", "zaehlt": "ja", "r": 5578}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt, wie viele Lagen ein gefaltetes Papier nach dem Falten hat. Bei jedem Falten wird das ganze schon gefaltete Paket in der Mitte gefaltet. Wie viele Lagen sind es nach dem 7. Falten?", "grafik": {"typ": "tabelle", "kopf": ["Falten", "1", "2", "3", "4"], "zeilen": [["Lagen", "2", "4", "8", "16"]]}}, "o": {"wert": 128}, "h": "Wie wächst die untere Zeile von Spalte zu Spalte?", "w": "Die Lagen verdoppeln sich jedes Mal: 2, 4, 8, 16, 32, 64, 128. Das ist 2⁷ = 128.", "form": "bruecke", "zaehlt": "ja", "r": 5579}]$auf$::jsonb),
    (44, 'zahlen.rechengesetze', 890, 42, $auf$[{"l": "punkt_strich", "t": "vorrang", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 4 + 6 · 3 − 2. Zeile 1: Ich rechne von links nach rechts: 4 + 6 = 10. Zeile 2: Dann 10 · 3 = 30. Zeile 3: Dann 30 − 2 = 28. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Welche Rechenart hat Vorrang?", "w": "Punkt vor Strich: Zuerst 6 · 3 = 18. Dann 4 + 18 = 22 und 22 − 2 = 20.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5891}, {"l": "punkt_strich", "t": "vorrang", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du rechnest 36 − 12 : 4 + 5. Welche Reihenfolge der Schritte ist richtig?"}, "a": ["36 − 12 = 24; dann 24 : 4 = 6; dann 6 + 5 = 11", "12 : 4 = 3; dann 36 − 3 = 33; dann 33 + 5 = 38", "12 : 4 = 3; dann 3 + 5 = 8; dann 36 − 8 = 28", "4 + 5 = 9; dann 12 : 9; dann 36 − das Ergebnis"], "o": {"index": 1}, "h": "Welches Zeichen hat Vorrang: Geteilt oder Minus?", "w": "Zuerst die Punktrechnung: 12 : 4 = 3. Dann von links: 36 − 3 = 33, 33 + 5 = 38.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5892}, {"l": "punkt_strich", "t": "vorrang", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Flohmarkt verkaufst du 6 Bücher zu je 3 € und 4 Spiele zu je 5 €. Du musst 8 € Standgebühr zahlen. Wie viel Euro bleiben dir?"}, "o": {"wert": 30, "einheit": "€"}, "h": "Rechne erst die Einnahmen aus, dann die Gebühr.", "w": "Bücher: 6 · 3 = 18. Spiele: 4 · 5 = 20. Einnahmen: 38. Davon 8 abziehen: 30 €.", "form": "anwenden", "zaehlt": "ja", "r": 5893}, {"l": "klammern", "t": "vorrang", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest (14 − 6) · 3 + 5. Die Klammer zuerst: 14 − 6 = ①. Dann mal 3: ① · 3 = ②. Zuletzt plus 5: ② + 5 = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [8, 24, 29]}, "h": "Erst die Klammer, dann Punkt, dann Strich.", "w": "14 − 6 = 8; 8 · 3 = 24; 24 + 5 = 29.", "form": "lueckenweg", "zaehlt": "nein", "r": 5894}, {"l": "klammern", "t": "vorrang", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche Zahl muss an der Stelle des Fragezeichens stehen? 3 · (? + 4) = 27"}, "o": {"wert": 5}, "h": "Mach zuerst die Umkehrung des Malnehmens: Was steht in der Klammer?", "w": "3 · Klammer = 27, also Klammer = 27 : 3 = 9. Dann ? + 4 = 9, also ? = 5.", "form": "umkehren", "zaehlt": "ja", "r": 5895}, {"l": "klammern", "t": "vorrang", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Klasse mit 24 Kindern besucht den Zoo. Jedes Kind zahlt 4 € Eintritt und 3 € für die Führung. Die Schule übernimmt davon 50 €. Wie viel Euro zahlen die Kinder zusammen?"}, "o": {"wert": 118, "einheit": "€"}, "h": "Was zahlt ein Kind insgesamt? Das steht in einer Klammer.", "w": "Ein Kind: 4 + 3 = 7 €. 24 Kinder: 24 · 7 = 168 €. Abzüglich 50 €: 118 €.", "form": "anwenden", "zaehlt": "ja", "r": 5896}, {"l": "termaufbau", "t": "terme", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim benennt den Term 3 · (5 + 2). Zeile 1: Ich rechne zuerst die Klammer: 5 + 2 = 7. Zeile 2: Dann bleibt 3 · 7 übrig. Zeile 3: Die letzte Rechnung ist das Plus aus der Klammer. Zeile 4: Darum ist der Term eine Summe. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Nach welcher Rechnung richtet sich der Name des Terms?", "w": "Der Name richtet sich nach der letzten Rechnung. Das ist das Malnehmen mit 3. Der Term ist ein Produkt.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5897}, {"l": "termaufbau", "t": "terme", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Welcher Term passt zum Text: „Vom Fünffachen von 4 werden 3 abgezogen“?"}, "a": ["5 · (4 − 3)", "5 − 4 · 3", "(5 + 4) · 3", "5 · 4 − 3"], "o": {"index": 3}, "h": "Das Fünffache von 4 ist eine Rechnung für sich.", "w": "Das Fünffache von 4 ist 5 · 4. Davon werden 3 abgezogen: 5 · 4 − 3 = 17.", "form": "bruecke", "zaehlt": "ja", "r": 5898}, {"l": "termaufbau", "t": "terme", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Fest kaufst du 4 Packungen Saft zu je 3 € und 2 Kuchen zu je 6 €. Du bezahlst mit einem 50-€-Schein. Wie viel Euro Rückgeld bekommst du?"}, "o": {"wert": 26, "einheit": "€"}, "h": "Stelle den Term auf: 50 minus alles, was du kaufst.", "w": "Saft: 4 · 3 = 12 €. Kuchen: 2 · 6 = 12 €. Zusammen 24 €. 50 − 24 = 26 €.", "form": "anwenden", "zaehlt": "ja", "r": 5899}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest 25 · 17 · 4 geschickt. Beim Malnehmen darfst du die Reihenfolge tauschen. Stelle das Paar nach vorn, das zusammen eine glatte Zahl ergibt: Das Paar ergibt ①. Die dritte Zahl ist 17: ① · 17 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [100, 1700]}, "h": "Bei Mal darfst du tauschen. Suche ein glattes Paar.", "w": "25 · 4 = 100. 100 · 17 = 1 700.", "form": "lueckenweg", "zaehlt": "nein", "r": 5900}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 37 + 48 + 63 + 52. Weg A rechnet von links nach rechts. Weg B fasst 37 + 63 und 48 + 52 zusammen. Wie groß ist die Summe?"}, "o": {"wert": 200}, "h": "Beide Wege geben dieselbe Zahl. Welcher geht schneller?", "w": "Weg A: 37 + 48 = 85, 85 + 63 = 148, 148 + 52 = 200. Weg B: 100 + 100 = 200.", "form": "zwei_wege", "zaehlt": "ja", "r": 5901}, {"l": "vorteil", "t": "gesetze", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Bäckerei liefert an 13 Schulen je 4 Kisten mit je 25 Brötchen. Wie viele Brötchen sind das insgesamt?"}, "o": {"wert": 1300}, "h": "25 und 4 passen gut zusammen.", "w": "4 · 25 = 100 Brötchen je Schule. 13 · 100 = 1 300.", "form": "anwenden", "zaehlt": "ja", "r": 5902}, {"l": "differenz_summe", "t": "gesetze", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 52 − 17 + 8 geschickt. Zeile 1: Das Minus gehört zur 17, das Plus gehört zur 8. Zeile 2: Ich tausche die Plätze von 17 und 8. Die Zeichen lasse ich an ihrem Platz stehen: 52 − 8 + 17. Zeile 3: 52 − 8 = 44 und 44 + 17 = 61. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was passiert mit dem Zeichen, wenn eine Zahl den Platz wechselt?", "w": "Beim Tauschen nimmt jede Zahl ihr Zeichen mit: 52 + 8 − 17 = 60 − 17 = 43.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5903}, {"l": "differenz_summe", "t": "gesetze", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 90 − 38 + 18. Weg A rechnet von links nach rechts. Weg B tauscht zu 90 + 18 − 38. Wie groß ist das Ergebnis?"}, "o": {"wert": 70}, "h": "Die Zahl nimmt ihr Zeichen mit, wenn du tauschst.", "w": "Weg A: 90 − 38 = 52, 52 + 18 = 70. Weg B: 90 + 18 = 108, 108 − 38 = 70.", "form": "zwei_wege", "zaehlt": "ja", "r": 5904}, {"l": "differenz_summe", "t": "gesetze", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Zu 37 wird eine Zahl addiert. Danach werden 15 abgezogen. Das Ergebnis ist 60. Welche Zahl wurde addiert?"}, "o": {"wert": 38}, "h": "Beginne beim Ergebnis und kehre die Schritte um, den letzten zuerst.", "w": "Rückwärts: 60 + 15 = 75. Dann 75 − 37 = 38. Probe: 37 + 38 − 15 = 60.", "form": "umkehren", "zaehlt": "ja", "r": 5905}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest 6 · 48 geschickt als 6 · (50 − 2). Es ist 6 · 50 = ①. Es ist 6 · 2 = ②. Ergebnis: ① − ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [300, 12, 288]}, "h": "Die 6 wird mit jedem Teil in der Klammer malgenommen.", "w": "6 · 50 = 300, 6 · 2 = 12, 300 − 12 = 288.", "form": "lueckenweg", "zaehlt": "nein", "r": 5906}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Die Tabelle beschreibt zwei Teile eines Rechtecks, die nebeneinander liegen. Welcher Term gibt die ganze Fläche?", "grafik": {"typ": "tabelle", "kopf": ["Teil", "Länge", "Breite"], "zeilen": [["links", "40 m", "7 m"], ["rechts", "3 m", "7 m"]]}}, "a": ["7 · 40 + 7 · 3", "7 · 40 + 3", "7 + 40 · 3", "7 · 40 · 3"], "o": {"index": 0}, "h": "Fläche jedes Teils: Länge mal Breite. Dann zusammenzählen.", "w": "Links: 40 · 7, rechts: 3 · 7. Zusammen 7 · 40 + 7 · 3 = 280 + 21 = 301 m². Das ist auch 7 · 43.", "form": "bruecke", "zaehlt": "ja", "r": 5907}, {"l": "verteilen", "t": "gesetze", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Gärtner pflanzt 9 Reihen mit je 98 Tulpen. Wie viele Tulpen sind das insgesamt?"}, "o": {"wert": 882}, "h": "98 ist fast 100. Rechne mit 100 − 2.", "w": "9 · 100 = 900. 9 · 2 = 18. 900 − 18 = 882 Tulpen.", "form": "anwenden", "zaehlt": "ja", "r": 5908}, {"l": "kopfrechnen", "t": "gesetze", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 7 · 38 im Kopf. Zeile 1: Ich zerlege 38 = 40 − 2. Zeile 2: 7 · 40 = 280. Zeile 3: 7 · 2 = 14. Zeile 4: Also 7 · 38 = 280 + 14 = 294. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Ist 38 größer oder kleiner als 40? Was heißt das für das Ergebnis?", "w": "38 ist kleiner als 40, also muss 14 abgezogen werden: 280 − 14 = 266.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5909}, {"l": "kopfrechnen", "t": "gesetze", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 15 · 18. Weg A: 15 · 20 − 15 · 2. Weg B: 10 · 18 + 5 · 18. Wie groß ist das Ergebnis?"}, "o": {"wert": 270}, "h": "Beide Wege führen zum gleichen Ergebnis.", "w": "Weg A: 300 − 30 = 270. Weg B: 180 + 90 = 270.", "form": "zwei_wege", "zaehlt": "ja", "r": 5910}, {"l": "kopfrechnen", "t": "gesetze", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zug hat 12 Wagen mit je 48 Sitzplätzen. Wie viele Sitzplätze sind das? Rechne geschickt im Kopf."}, "o": {"wert": 576}, "h": "Zerlege die 12 in 10 + 2.", "w": "10 · 48 = 480, 2 · 48 = 96. 480 + 96 = 576 Plätze.", "form": "anwenden", "zaehlt": "ja", "r": 5911}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du rechnest (−6) · 7. Ohne Vorzeichen: 6 · 7 = ①. Die Vorzeichen sind verschieden, also hat das Ergebnis den Betrag ① mit dem passenden Vorzeichen: ②. Bei (−6) · (−7) sind die Vorzeichen gleich. Dieses Ergebnis ist um ③ größer als ②.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [42, -42, 84]}, "h": "Verschiedene Vorzeichen: minus. Gleiche Vorzeichen: plus.", "w": "6 · 7 = 42. (−6) · 7 = −42. (−6) · (−7) = 42. 42 − (−42) = 84.", "form": "lueckenweg", "zaehlt": "nein", "r": 5912}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Welche Zahl mal (−5) ergibt 40?"}, "o": {"wert": -8}, "h": "Rechne mit der Umkehraufgabe. Achte auf das Vorzeichen.", "w": "40 : (−5) = −8. Probe: (−8) · (−5) = 40.", "form": "umkehren", "zaehlt": "ja", "r": 5913}, {"l": "mal_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Dein Kontostand sinkt an 5 Tagen um je 12 €. Welche Rechnung gibt die Änderung insgesamt?"}, "a": ["5 + (−12)", "(−5) · (−12)", "5 · (−12)", "(−12) : 5"], "o": {"index": 2}, "h": "5-mal dieselbe Änderung heißt: malnehmen. Sinken heißt: minus.", "w": "Jeden Tag −12 €, an 5 Tagen: 5 · (−12) = −60 €.", "form": "bruecke", "zaehlt": "ja", "r": 5914}, {"l": "geteilt_ganz", "t": "ganz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet (−72) : (−9). Zeile 1: Beide Zahlen sind negativ. Zeile 2: Zwei Minuszeichen ergeben beim Teilen wieder ein Minus. Zeile 3: Also ist (−72) : (−9) = −8. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was ergeben gleiche Vorzeichen beim Teilen: Plus oder Minus?", "w": "Gleiche Vorzeichen ergeben Plus. (−72) : (−9) = 8. Probe: 8 · (−9) = −72.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5915}, {"l": "geteilt_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl geteilt durch (−6) ergibt 7. Welche Zahl ist es?"}, "o": {"wert": -42}, "h": "Kehre das Teilen um. Beachte das Vorzeichen.", "w": "Zahl : (−6) = 7, also Zahl = 7 · (−6) = −42. Probe: (−42) : (−6) = 7.", "form": "umkehren", "zaehlt": "ja", "r": 5916}, {"l": "geteilt_ganz", "t": "ganz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Taucher sinkt in 8 Minuten gleichmäßig von 0 m auf −96 m. Wie ändert sich seine Höhe in jeder Minute (in Meter, mit Vorzeichen)?"}, "o": {"wert": -12, "einheit": "m"}, "h": "Teile die gesamte Änderung durch die Zahl der Minuten.", "w": "−96 m : 8 = −12 m. Er sinkt jede Minute um 12 m.", "form": "anwenden", "zaehlt": "ja", "r": 5917}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Löse 6 · x = −84. Die Umkehraufgabe zu Mal ist Geteilt: x = (−84) : 6 = ①. Nun sei y : 5 = ①. Die Umkehraufgabe zu Geteilt ist Mal: y = ① · 5 = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-14, -70]}, "h": "Mal kehrst du mit Geteilt um, Geteilt mit Mal.", "w": "(−84) : 6 = −14. (−14) · 5 = −70.", "form": "lueckenweg", "zaehlt": "nein", "r": 5918}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du sollst x : 4 = −9 lösen. Welcher Weg ist richtig?"}, "a": ["x = (−9) : 4", "x = 4 : (−9)", "x = (−9) · 4 = −36", "x = (−9) + 4 = −5"], "o": {"index": 2}, "h": "Welche Rechnung macht das Teilen durch 4 rückgängig?", "w": "Teilen durch 4 kehrst du mit Malnehmen um: x = (−9) · 4 = −36. Probe: (−36) : 4 = −9.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5919}, {"l": "umkehraufgabe_mal", "t": "gleichungen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Konto verliert jeden Monat denselben Betrag. Die Änderung nach 7 Monaten ist −133 €. Wie ändert sich das Konto pro Monat (in Euro, mit Vorzeichen)?"}, "o": {"wert": -19, "einheit": "€"}, "h": "7 gleiche Änderungen ergeben −133. Was machst du, um eine zu finden?", "w": "−133 € : 7 = −19 €. Probe: 7 · (−19) = −133.", "form": "anwenden", "zaehlt": "ja", "r": 5920}, {"l": "ueberschlag", "t": "verfahren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim überschlägt 4 987 · 21. Das genaue Ergebnis ist 104 727. Zeile 1: Ich runde 4 987 auf Tausender: 4 000. Zeile 2: Ich runde 21 auf Zehner: 20. Zeile 3: Überschlag: 4 000 · 20 = 80 000. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Auf welche Zahl rundest du 4 987 auf Tausender? Schau auf die Hunderterziffer.", "w": "4 987 rundet man auf 5 000, denn die Hunderterziffer 9 ist 5 oder mehr. Überschlag: 5 000 · 20 = 100 000. Das passt zum genauen Ergebnis.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5921}, {"l": "ueberschlag", "t": "verfahren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Überschlage 612 + 349 + 98. Weg A rundet auf Hunderter und addiert. Weg B rundet auf Zehner und addiert. Um wie viel ist der Überschlag von Weg B größer als der von Weg A?"}, "o": {"wert": 60}, "h": "Runde in jedem Weg alle drei Zahlen, dann addiere.", "w": "Weg A: 600 + 300 + 100 = 1 000. Weg B: 610 + 350 + 100 = 1 060. Unterschied: 60.", "form": "zwei_wege", "zaehlt": "ja", "r": 5922}, {"l": "ueberschlag", "t": "verfahren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Schule bestellt 28 Pakete Papier mit je 312 Blatt. Sie braucht 10 000 Blatt. Wie viele Blatt fehlen noch? (Überschlag zur Kontrolle: 30 · 300 ist etwa 9 000.)"}, "o": {"wert": 1264}, "h": "Rechne die Zahl der Blätter genau aus. Dein Überschlag sagt etwa 1 000.", "w": "28 · 312 = 8 736. 10 000 − 8 736 = 1 264 Blatt fehlen.", "form": "anwenden", "zaehlt": "ja", "r": 5923}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Schriftlich 123 · 45. Erst mit der Einerziffer 5: 123 · 5 = ①. Dann mit der Zehnerziffer 4: Sie steht an der Zehnerstelle, du rechnest also mit ihrem Wert. Das Teilergebnis ist ②. Beides addieren: ① + ② = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [615, 4920, 5535]}, "h": "Bei der Zehnerziffer wandert das Ergebnis eine Stelle nach links.", "w": "123 · 5 = 615. 123 · 40 = 4 920. 615 + 4 920 = 5 535.", "form": "lueckenweg", "zaehlt": "nein", "r": 5924}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl mal 36 ergibt 1 692. Welche Zahl ist es? Rechne schriftlich geteilt."}, "o": {"wert": 47}, "h": "Kehre das Malnehmen mit Teilen um.", "w": "1 692 : 36 = 47. Probe: 47 · 36 = 1 692.", "form": "umkehren", "zaehlt": "ja", "r": 5925}, {"l": "schriftlich", "t": "verfahren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Lastwagen bringt 24 Kisten mit je 135 Flaschen. Die Flaschen werden gleichmäßig auf 15 Tische verteilt. Wie viele Flaschen liegen auf einem Tisch?"}, "o": {"wert": 216}, "h": "Erst alle Flaschen ausrechnen, dann teilen.", "w": "24 · 135 = 3 240 Flaschen. 3 240 : 15 = 216 Flaschen je Tisch.", "form": "anwenden", "zaehlt": "ja", "r": 5926}, {"l": "schriftlich_geteilt", "t": "verfahren", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim rechnet 7 308 : 18 schriftlich. Zeile 1: Die 7 ist zu klein, ich nehme 73. Es gilt 73 = 4 · 18 + 1. Ich schreibe 4 ins Ergebnis und merke den Rest 1. Zeile 2: Ich hole die 0 herunter. 10 : 18 geht nicht, also schreibe ich nichts ins Ergebnis. Zeile 3: Ich hole die 8 herunter: 108 : 18 = 6. Zeile 4: Ergebnis: 46. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 1}, "h": "Jede heruntergeholte Ziffer bringt eine Ziffer ins Ergebnis. Was schreibst du, wenn der Teiler nicht passt?", "w": "Passt der Teiler nicht, schreibst du eine 0 ins Ergebnis. 7 308 : 18 = 406. Probe: 406 · 18 = 7 308.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5927}, {"l": "schriftlich_geteilt", "t": "verfahren", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du teilst 5 472 durch 24 schriftlich. Was hilft dir dabei am meisten?"}, "a": ["Die Vielfachen von 24 aufschreiben: 24, 48, 72, 96, …", "24 durch 5 472 teilen", "Die Ziffern von 5 472 addieren und durch 24 teilen", "Nur 5 : 24 rechnen und Nullen anhängen"], "o": {"index": 0}, "h": "Welche Hilfsliste zeigt dir, wie oft 24 hineinpasst?", "w": "Mit den Vielfachen von 24 siehst du schnell, wie oft 24 in 54, 67 und 192 passt. Ergebnis: 5 472 : 24 = 228.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5928}, {"l": "schriftlich_geteilt", "t": "verfahren", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Eine Zahl geteilt durch 25 ergibt 328. Welche Zahl ist es?"}, "o": {"wert": 8200}, "h": "Kehre das Teilen mit Malnehmen um. Rechne schriftlich.", "w": "328 · 25 = 8 200. Probe: 8 200 : 25 = 328.", "form": "umkehren", "zaehlt": "ja", "r": 5929}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ich denke mir eine Zahl. Ich addiere 12 und multipliziere die Summe mit 4. Dann erhalte ich 120. Rückwärts kehrst du zuerst den letzten Schritt um: Das ergibt ①. Danach kehrst du den ersten Schritt um: ① wird zu ②. Die gedachte Zahl ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [30, 18]}, "h": "Beginne am Ende und kehre den letzten Schritt zuerst um.", "w": "120 : 4 = 30. 30 − 12 = 18. Probe: (18 + 12) · 4 = 120.", "form": "lueckenweg", "zaehlt": "nein", "r": 5930}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Von einem Betrag werden erst 35 € abgezogen. Der Rest wird durch 3 geteilt. Es bleiben 24 €. Wie groß war der Betrag?"}, "o": {"wert": 107, "einheit": "€"}, "h": "Beginne beim Rest und kehre den letzten Schritt zuerst um.", "w": "Rückwärts: 24 · 3 = 72. Dann 72 + 35 = 107. Probe: (107 − 35) : 3 = 24.", "form": "umkehren", "zaehlt": "ja", "r": 5931}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt drei Schritte, die nacheinander gerechnet werden. Am Ende kommt 41 heraus. Mit welcher Zahl wurde begonnen?", "grafik": {"typ": "tabelle", "kopf": ["Schritt", "1", "2", "3"], "zeilen": [["Rechnung", "+ 8", "· 5", "− 4"]]}}, "o": {"wert": 1}, "h": "Lies die Tabelle von rechts nach links und kehre jeden Schritt um.", "w": "Rückwärts: 41 + 4 = 45. 45 : 5 = 9. 9 − 8 = 1. Probe: ((1 + 8) · 5) − 4 = 41.", "form": "bruecke", "zaehlt": "ja", "r": 5932}]$auf$::jsonb),
    (53, 'stochastik.kombinatorik', 533, 21, $auf$[{"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Eisbecher hat eine Sorte (Vanille, Schoko, Erdbeere) und eine Soße (Karamell, Himbeer). Die Sorte Vanille lässt sich mit ① Soßen kombinieren. Das gilt für jede Sorte. Alle Becher zusammen: Zahl der Sorten mal ① = ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 6]}, "h": "Zähle die Soßen, die zu einer einzigen Sorte passen.", "w": "Zu Vanille passen 2 Soßen, genauso zu Schoko und Erdbeere. 3 · 2 = 6 Becher.", "form": "lueckenweg", "zaehlt": "nein", "r": 5534}, {"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Die Tabelle zeigt die Eisbecher mit Vanille und mit Schoko. Jedes Feld steht für einen Becher. Die Zeile für Erdbeere fehlt noch. Sie hätte dieselben Soßen wie die anderen Zeilen. Wie viele Becher-Felder hätte die Tabelle insgesamt, wenn die Zeile für Erdbeere dazukäme?", "grafik": {"typ": "tabelle", "kopf": ["", "Karamell", "Himbeer"], "zeilen": [["Vanille", "Becher 1", "Becher 2"], ["Schoko", "Becher 3", "Becher 4"]]}}, "o": {"wert": 6}, "h": "Wie viele Becher stünden in der Zeile für Erdbeere? Wie viele Zeilen hätte die Tabelle dann?", "w": "Jede Zeile hat 2 Felder (2 Soßen). Mit Erdbeere sind es 3 Zeilen: 3 · 2 = 6 Becher.", "form": "bruecke", "zaehlt": "ja", "r": 5535}, {"l": "systematisch", "t": "systematisch", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Pizzeria bietet 3 Teigarten und 4 Beläge an. Jede Pizza hat genau eine Teigart und genau einen Belag. Kim will jede mögliche Kombination genau einmal probieren, eine Pizza pro Tag. Wie viele Tage braucht sie?"}, "o": {"wert": 12}, "h": "Halte eine Teigart fest und zähle die Beläge. Dann die nächste Teigart.", "w": "Zu jeder der 3 Teigarten gibt es 4 Beläge: 3 · 4 = 12 Tage.", "form": "anwenden", "zaehlt": "ja", "r": 5536}, {"l": "zaehlprinzip", "t": "zaehlprinzip", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Eine Schule bietet Menüs an: 3 Vorspeisen, 4 Hauptgerichte und 2 Nachspeisen. Jedes Menü hat von jeder Sorte genau eines. Kim zählt die Menüs. Zeile 1: Es gibt 3 Vorspeisen. Zeile 2: Zu jeder Vorspeise passen 4 Hauptgerichte: 3 · 4 = 12 Paare. Zeile 3: Zu jedem der 12 Paare gibt es 2 Nachspeisen. Zeile 4: Also gibt es 12 + 2 = 14 Menüs. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie werden Anzahlen verbunden, wenn man nacheinander wählt?", "w": "Wahlen nacheinander werden malgenommen: 12 · 2 = 24 Menüs.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5537}, {"l": "zaehlprinzip", "t": "zaehlprinzip", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Fahrrad gibt es in 4 Farben, 3 Größen und 2 Lenkerformen. Jedes Rad hat von jedem eines. Weg A multipliziert die drei Anzahlen. Weg B zählt alle Räder einer Farbe auf und addiert diese Anzahl dann für jede Farbe. Wie viele verschiedene Räder gibt es?"}, "o": {"wert": 24}, "h": "Beide Wege führen zur selben Zahl.", "w": "Weg A: 4 · 3 · 2 = 24. Weg B: Je Farbe gibt es 3 · 2 = 6 Räder. Für 4 Farben: 6 + 6 + 6 + 6 = 24.", "form": "zwei_wege", "zaehlt": "ja", "r": 5538}, {"l": "zaehlprinzip", "t": "zaehlprinzip", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Nummernschloss hat 3 Rädchen. Auf jedem Rädchen kann man eine Ziffer von 0 bis 9 einstellen, auch dieselbe Ziffer mehrmals. Wie viele Einstellungen gibt es?"}, "o": {"wert": 1000}, "h": "Wie viele Ziffern gibt es von 0 bis 9? Ein Rädchen nach dem anderen.", "w": "Jedes Rädchen hat 10 Möglichkeiten: 10 · 10 · 10 = 1 000 Einstellungen.", "form": "anwenden", "zaehlt": "ja", "r": 5539}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Vier Kinder setzen sich auf vier Plätze nebeneinander, jedes auf einen anderen. Auf den ersten Platz kann jedes der 4 Kinder. Für den zweiten Platz bleiben ① Kinder. Für den dritten Platz bleibt eins weniger als beim zweiten: ②. Zusammen: 4 · ① · ② · 1 = ③ Reihenfolgen.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 2, 24]}, "h": "Jedes Kind sitzt nur auf einem Platz. Die Auswahl wird jedes Mal um eins kleiner.", "w": "Platz 2: 3 Kinder, Platz 3: 2 Kinder, Platz 4: 1 Kind. 4 · 3 · 2 · 1 = 24.", "form": "lueckenweg", "zaehlt": "nein", "r": 5540}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Mehrere Kinder stellen sich in einer Reihe auf, alle verschieden. Dafür gibt es 120 mögliche Reihenfolgen. Wie viele Kinder sind es?"}, "o": {"wert": 5}, "h": "Probiere nacheinander 3 · 2 · 1, dann 4 · 3 · 2 · 1 und so weiter.", "w": "5 · 4 · 3 · 2 · 1 = 120. Es sind 5 Kinder. Bei 4 Kindern wären es nur 24 Reihenfolgen.", "form": "umkehren", "zaehlt": "ja", "r": 5541}, {"l": "reihenfolgen", "t": "reihenfolgen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Bei einer Staffel laufen 4 Kinder nacheinander. Jedes Kind läuft genau einmal. Die Trainerin legt fest, in welcher Reihenfolge sie laufen. Wie viele Möglichkeiten hat sie?"}, "o": {"wert": 24}, "h": "Für den ersten Läufer hat sie 4 Kinder zur Wahl. Dann wird die Auswahl kleiner.", "w": "4 · 3 · 2 · 1 = 24 Reihenfolgen.", "form": "anwenden", "zaehlt": "ja", "r": 5542}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 2, "g": "darstellung", "y": "zahl", "f": {"text": "Das Baumdiagramm zeigt zwei Münzwürfe nacheinander (K = Kopf, Z = Zahl). Bei wie vielen Pfaden kommt mindestens einmal Z vor?", "grafik": {"typ": "baum", "aeste": [{"text": "K", "aeste": [{"text": "K"}, {"text": "Z"}]}, {"text": "Z", "aeste": [{"text": "K"}, {"text": "Z"}]}]}}, "o": {"wert": 3}, "h": "Zähle alle Pfade und streiche den, bei dem kein Z vorkommt.", "w": "Es gibt 4 Pfade: KK, KZ, ZK, ZZ. Nur KK hat kein Z. Es bleiben 3 Pfade.", "form": "bruecke", "zaehlt": "ja", "r": 5543}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Du willst alle Ergebnisse von drei Münzwürfen nacheinander zählen. Welcher Weg ist sicher?"}, "a": ["Die Äste einer Stufe zählen und mit 3 malnehmen: 2 · 3 = 6", "Die Äste addieren: 2 + 2 + 2 = 6", "Ein Baumdiagramm mit drei Stufen zeichnen und die Pfade zählen: 2 · 2 · 2 = 8", "Nur Kopf-Kopf-Kopf und Zahl-Zahl-Zahl zählen: 2"], "o": {"index": 2}, "h": "Jeder Pfad von der Wurzel bis zum Ende ist ein Ergebnis.", "w": "Jeder Wurf hat 2 Äste, jeder Ast teilt sich wieder in 2: 2 · 2 · 2 = 8 Pfade.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5544}, {"l": "baumdiagramm", "t": "baumdiagramm", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Baumdiagramm teilt sich die Wurzel in 3 Äste. Jeder dieser Äste teilt sich in gleich viele weitere Äste. Es gibt am Ende 12 Pfade. In wie viele Äste teilt sich jeder der ersten Äste?"}, "o": {"wert": 4}, "h": "Die Zahl der Pfade ist das Produkt der Astzahlen. Welche Zahl mal 3 gibt 12?", "w": "3 · ? = 12, also ? = 12 : 3 = 4 Äste.", "form": "umkehren", "zaehlt": "ja", "r": 5545}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Gesucht sind dreistellige Zahlen mit lauter verschiedenen Ziffern, deren erste Ziffer ungerade ist. Wir rechnen im Dezimalsystem. Für die erste Ziffer gibt es ① Möglichkeiten. Für die zweite Ziffer darf jede Ziffer außer der ersten stehen, auch die 0: Das sind ② Möglichkeiten. Für die dritte Ziffer bleibt eine weniger als bei der zweiten: ③. Zusammen ① · ② · ③ = ④.", "schablone": "① = □; ② = □; ③ = □; ④ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [5, 9, 8, 360]}, "h": "Beginne mit der Stelle, für die eine Bedingung gilt. Welche Ziffern sind ungerade?", "w": "Ungerade Ziffern: 1, 3, 5, 7, 9. Das sind 5 Möglichkeiten. Zweite Ziffer: 10 minus die erste, also 9. Dritte Ziffer: 8. Zusammen 5 · 9 · 8 = 360.", "form": "lueckenweg", "zaehlt": "nein", "r": 5546}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine PIN hat 4 Ziffern. Die erste Ziffer darf nicht 0 sein, die anderen dürfen beliebig sein, auch gleich. Weg A rechnet 9 · 10 · 10 · 10. Weg B nimmt alle 10 000 Ziffernfolgen und zieht die 1 000 Folgen mit 0 vorn ab. Wie viele PINs gibt es?"}, "o": {"wert": 9000}, "h": "Beide Wege geben dieselbe Zahl.", "w": "Weg A: 9 · 1 000 = 9 000. Weg B: 10 000 − 1 000 = 9 000.", "form": "zwei_wege", "zaehlt": "ja", "r": 5547}, {"l": "bedingungen", "t": "bedingungen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Team hat 6 Kinder. Es wird ein Kapitän und eine Stellvertretung gewählt. Dasselbe Kind kann nicht beides sein. Wie viele Möglichkeiten gibt es?"}, "o": {"wert": 30}, "h": "Beginne mit dem Kapitän. Wie viele Kinder bleiben für die Stellvertretung?", "w": "Kapitän: 6 Möglichkeiten. Stellvertretung: 5 Kinder bleiben. 6 · 5 = 30.", "form": "anwenden", "zaehlt": "ja", "r": 5548}, {"l": "grenzen", "t": "grenzen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Beim Fest begrüßen sich 6 Kinder, indem jedes Paar einmal die Hand gibt. Kim zählt die Handschläge. Zeile 1: Jedes Kind gibt 5 anderen die Hand. Zeile 2: 6 · 5 = 30, wenn man jedes Kind einzeln mitzählt. Zeile 3: Ich teile nicht durch 2, denn jeder Handschlag zählt nur einmal. Zeile 4: Es gibt 30 Handschläge. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Wie oft ist ein Handschlag zwischen A und B in deiner Rechnung gezählt?", "w": "Jeder Handschlag wird zweimal gezählt (A mit B und B mit A). Darum teilt man durch 2: 30 : 2 = 15 Handschläge.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5549}, {"l": "grenzen", "t": "grenzen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei einem Turnier spielt jede Mannschaft genau einmal gegen jede andere. Es gibt 21 Spiele. Wie viele Mannschaften nehmen teil?"}, "o": {"wert": 7}, "h": "Probiere: n Mannschaften geben n · (n − 1) : 2 Spiele.", "w": "Bei 7 Mannschaften: 7 · 6 : 2 = 21 Spiele. Bei 6 wären es nur 15.", "form": "umkehren", "zaehlt": "ja", "r": 5550}, {"l": "grenzen", "t": "grenzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Verein hat 8 Mitglieder. Zwei von ihnen fahren gemeinsam zu einem Treffen. Es kommt nicht darauf an, wer zuerst genannt wird. Wie viele verschiedene Paare sind möglich?"}, "o": {"wert": 28}, "h": "Zähle erst alle geordneten Paare und teile dann, weil die Reihenfolge egal ist.", "w": "8 · 7 = 56 geordnete Paare. Jedes Paar ist doppelt gezählt: 56 : 2 = 28.", "form": "anwenden", "zaehlt": "ja", "r": 5551}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim zählt Buchstabenfolgen aus den vier Buchstaben A, B, C und D. Die Folgen müssen keine Bedeutung haben. Jeder Buchstabe darf in einer Folge genau einmal vorkommen, jede Folge hat vier Buchstaben. Zeile 1: Für den ersten Buchstaben gibt es 4 Möglichkeiten. Zeile 2: Für den zweiten bleiben 3, für den dritten 2, für den vierten 1. Zeile 3: Die Buchstaben werden nacheinander gewählt. Zeile 4: Also gibt es 4 + 3 + 2 + 1 = 10 Folgen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Wie verbindet man Anzahlen bei Wahlen nacheinander?", "w": "Nacheinander heißt malnehmen: 4 · 3 · 2 · 1 = 24 Folgen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 5552}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Drei Freunde bestellen jeweils ein Getränk aus 4 Sorten. Dieselbe Sorte darf mehrfach bestellt werden. Es zählt, wer was bestellt: Nimmt Freund 1 Cola und Freund 2 Tee, ist das etwas anderes, als wenn es umgekehrt ist. Welche Rechnung zählt die möglichen Bestellungen?"}, "a": ["4 · 4 · 4", "4 · 3 · 2", "4 + 4 + 4", "4 · 3"], "o": {"index": 0}, "h": "Darf sich etwas wiederholen? Dann bleibt die Auswahl bei jeder Wahl gleich groß.", "w": "Jeder der 3 Freunde hat 4 Sorten zur Wahl. 4 · 4 · 4 = 64 Bestellungen.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 5553}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Bei 3 Wahlen nacheinander gibt es jedes Mal gleich viele Möglichkeiten, und dieselbe Möglichkeit darf wiederholt werden. Insgesamt gibt es 125 Fälle. Wie viele Möglichkeiten hat jede einzelne Wahl?"}, "o": {"wert": 5}, "h": "Welche Zahl ergibt als Produkt aus drei gleichen Faktoren 125?", "w": "5 · 5 · 5 = 125. Jede Wahl hat 5 Möglichkeiten.", "form": "umkehren", "zaehlt": "ja", "r": 5554}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 174 then fehler := fehler || ('zusammen ' || gesamt || ' statt 174')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
select einheit_id, count(*) filter (where pool = 'uebung') as uebungen, count(*) filter (where form is not null) as mit_form from schule.aufgabe where einheit_id in (1, 28, 39, 41, 44, 53) group by 1 order by 1;
